    .SCLK(SCLK), 
    .SS(SS), 
    .MOSI(MOSI), 
    .DATA(DATA)
  );

  initial begin
    // Initialize Inputs
    SPI_CLK = 0;
    SCLK = 0;
    SS = 1;
    MOSI = 0;

    // Wait 100 ns for global reset to finish
    #100;

    // Add stimulus here
    SPI_CLK = 1; SCLK = 1; SS = 0; MOSI = 1; #20;
    SPI_CLK = 0; SCLK = 0; MOSI = 1; #20;
    SPI_CLK = 1; SCLK = 1; MOSI = 1; #20;
    SPI_CLK = 0; SCLK = 0; MOSI = 0; #20;
