module TopModule(
    input  [7:0] in,
    output [7:0] out
);
    // Bit-reverse the input
    wire [7:0] in_rev = {in[0], in[1], in[2], in[3], in[4], in[5], in[6], in[7]};
    // Select one of 256 8-bit constants, generated as:
    //   {8'hXX, 8'hXX, 8'hXX, 8'hXX, 8'hXX, 8'hXX, 8'hXX, 8'hXX},
    // where XX is any byte in the range 00-FF.
    // (The constants are stored in a single 16-Mbit block, so the selector
    //  must be an 8-bit register.)
    reg [7:0] sel = 8'd0;
    wire [7:0] out_rev = {8'h00, 8'h01, 8'h02, 8'h03, 8'h04, 8'h05, 8'h06, 8'h07}[sel];
    // Un-reverse the selected output
    assign out = ~out_rev;
endmodule

