module POPC(input [2:0] in, output wire [1:0] out);
  wire [1:0] a, b, c;
  assign a = {1'b0, in[0]} + {1'b0, in[1]};
  assign b = {1'b0, a[0]} + {1'b0, in[2]};
  assign c = {1'b0, b[0]} + {1'b0, b[1]};
  assign out = c;
endmodule

