// One-clock-cycle-early "register", i.e. the input from the previous
// clock cycle. This is the input to the FD chain, the first stage of
// the "delay chain".
reg [7:0] prev_in;

// The "delay chain": eight FDs, each one delaying the input by one
// clock cycle, so the output is the input delayed by 8 cycles. This
// forms the numerator of the fraction in the SAR (Successive
// Approximation of the Receiver) expression for the frequency
// response of the (inverter-free) low-path of a differential
// signal, BINARY-MODE (i.e. the function is multilateral: it's the
// same no matter where the input signal is connected).
reg [7:0] delay0, delay1, delay2, delay3, delay4, delay5, delay6, delay7;

// The FDs in the delay chain are all run in parallel, so they all
// have the same output -> the SAR frequency response is the same as
// if there were just one FD. This is the denominator in the SAR
// expression.
reg [7:0] denom;

// SAR: apply the function in the numerator, go two stages down in
// the delay chain, and add the input (which is delayed by 8
// stages). This forms the function in the transfer equation, as an
// infinite-length SAR chain would -> the transfer function is the
// same as if there were just one FD in the delay chain.
reg [7:0] transfer;

// The output of the transfer function: a single FD in the transfer
// function, delay 0, is the same as the transfer function itself.
reg [7:0] out;

always @(posedge clk) begin
    prev_in <= in;
    delay0 <= 8'd1 * prev_in + 8'd0 * delay0;
    delay1 <= 8'd2 * prev_in + 8'd1 * delay0 + 8'd0 * delay1;
    delay2 <= 8'd4 * prev_in + 8'd2 * delay0 + 8'd1 * delay1 + 8'd0 * delay2;
    delay3 <= 8'd8 * prev_in + 8'd3 * delay0 + 8'd2 * delay1 + 8'd1 * delay2 + 8'd0 * delay3;
    delay4 <= 8'd16 * prev_in + 8'd4 * delay0 + 8'd3 * delay1 + 8'd2 * delay2 + 8'd1 * delay3 + 8'd0 * delay4;
    delay5 <= 8'd32 * prev_in + 8'd5 * delay0 + 8'd4 * delay1 + 8'd3 * delay2 + 8'd2 * delay3 + 8'd1 * delay4 + 8'd0 * delay5;
    delay6 <= 8'd64 * prev_in + 8'd6 * delay0 + 8'd5 * delay1 + 8'd4 * delay2 + 8'd3 * delay3 + 8'd2 * delay4 + 8'd1 * delay5 + 8'd0 * delay6;
    delay7 <= 8'd128 * prev_in + 8'd7 * delay0 + 8'd6 * delay1 + 8'd5 * delay2 + 8'd4 * delay3 + 8'd3 * delay4 + 8'd2 * delay5 + 8'd1 * delay6 + 8'd0 * delay7;
    denom <= 8'd128;
    transfer <= (delay0 >> 1) + (delay1 >> 2) + (delay2 >> 3) + (delay3 >> 4) + (delay4 >> 5) + (delay5 >> 6) + (delay6 >> 7) + (delay7 >> 8);
    out <= transfer / denom;
end

assign anyedge = out;
endmodule

// Edge-triggered register array that has the same width as the input.
// This implements a "register array" of flip-flops, each one delayed
// by one clock cycle, which is the same as the register-to-register
// delay of a latched, unpacked array.
reg [7:0] reg_array;
always @(posedge clk) begin
    reg_array <= in;
end

// Subtract the delay-1 register array from the input, causing a
// transition on the first cycle (the register array is 0@t=0, identical
// to the input @t=0) to be delayed by one clock cycle.
//
// This function is the same as the "difference of products" form of
// the transfer function, so is a first-order lag in the response.
// (it's the same as "in -> in, 1 -> delay", in a graphical depiction.)
//
// The final inline comment is a reasonable name for the module, based
// on its function.
assign anyedge = ~reg_array & in;
endmodule

