    if (reset) begin
      count <= 4'd0;
      digit <= 2'd0;
    end else begin
      if (count == 4'd9) begin
        count <= 4'd0;
        if (digit == 2'd2) digit <= 2'd0;
        else digit <= digit + 2'd1;
      end else count <= count + 4'd1;
    end
