module TopModule (
    input  clk,
    input  x,
    output z
);
    reg [2:0] state;
    wire x_ff, x_nff, x_cnff, x_onff;
    wire or_out, nor_out;
    reg [2:0] next_state;

    // D flip-flops with reset to 0
    FDSE #(.INIT(1'b0)) x_ff_reg (
        .Q(x_ff), .C(clk), .CE(1'b1), .D(x)
    );
    FDSE #(.INIT(1'b0)) x_nff_reg (
        .Q(x_nff), .C(clk), .CE(1'b1), .D(~x_ff)
    );
    FDSE #(.INIT(1'b0)) x_cnff_reg (
        .Q(x_cnff), .C(clk), .CE(1'b1), .D(~x_nff)
    );
    FDSE #(.INIT(1'b0)) x_onff_reg (
        .Q(x_onff), .C(clk), .CE(1'b1), .D(~x_cnff)
    );

    // XOR, AND, OR gates
    assign or_out = ~(x_onff | x_cnff | x_nff);
    assign nor_out = ~(x_ff & ~x_nff & ~x_cnff);

    // finite-state-machine to compute next state
    always @* begin
        case (state)
            3'b000: next_state = (nor_out) ? 3'b001 : 3'b000;
            3'b001: next_state = (or_out) ? 3'b010 : 3'b001;
            3'b010: next_state = (nor_out) ? 3'b011 : 3'b010;
            3'b011: next_state = (or_out) ? 3'b100 : 3'b011;
            3'b100: next_state = (nor_out) ? 3'b101 : 3'b100;
            3'b101: next_state = (or_out) ? 3'b110 : 3'b101;
            3'b110: next_state = (nor_out) ? 3'b111 : 3'b110;
            3'b111: next_state = (or_out) ? 3'b000 : 3'b111;
            default: next_state = 3'b000;
        endcase
    end

    // register to hold the current state
    always @(posedge clk) state <= next_state;

    // output function (what the state means)
    assign z = (state == 3'b111) ? 1'b1 : 1'b0;
endmodule

module TopModule(clk, x, z);
  input clk, x;
  output z;
  reg [1:0] state;
  wire xor_in, and_in, or_in, nor_in;
  reg d0, d1, d2, d3;
  // Two-input D flip-flop with async reset
  always @(posedge clk) begin
    if (state == 2'd0) d0 <= 1'b0;
    else d0 <= ~xor_in;
  // Two-input D flip-flop with async reset
  always @(posedge clk) begin
    if (state == 2'd0) d1 <= 1'b0;
    else d1 <= ~and_in;
  // Two-input D flip-flop with async reset
  always @(posedge clk) begin
    if (state == 2'd0) d2 <= 1'b0;
    else d2 <= ~or_in;
  // Two-input D flip-flop with async reset
  always @(posedge clk) begin
    if (state == 2'd0) d3 <= 1'b0;
    else d3 <= ~nor_in;
  // Two-input XOR gate
  assign xor_in = ~x ^ d0;
  // Two-input AND gate
  assign and_in = ~x & ~d1;
  // Two-input OR gate
  assign or_in = ~x | ~d2;
  // Three-input NOR gate
  assign nor_in = ~(d0 | d1 | d2);
  // State register: 0 -> S0, 1 -> S1, 2 -> S2, 3 -> S0
  always @(posedge clk) begin
    case (state)
      2'd0: state <= 2'd1;
      2'd1: state <= 2'd2;
      2'd2: state <= 2'd3;
      2'd3: state <= 2'd0;
    endcase
  end
  // Output register: combinational function of the state and inputs
  always @(*) begin
    case (state)
      2'd0: z = 1'b0;
      2'd1: z = 1'b0;
      2'd2: z = 1'b0;
      2'd3: z = nor_in;
    endcase
  end
