module TopModule(input clk, input areset, input train_valid, input train_taken, output reg [1:0] state);
    always @(posedge clk) begin
        if (areset) state <= 2'b01;
        else begin
            case ({train_valid, train_taken})
                2'b00: state <= state;
                2'b01: state <= state - 2'd1;
                2'b10: state <= state + 2'd1;
                2'b11: state <= state + 2'd2;
            endcase
        end
