module TopModule(
    input  clk,
    input  areset,
    input  train_valid,
    input  train_taken,
    output reg [1:0] state
);
    reg [1:0] next_state;
    always @(*) begin
        case ({train_valid, state})
            2'b00: next_state = 2'b01;
            2'b01: next_state = train_taken ? 2'b10 : 2'b01;
            2'b10: next_state = train_taken ? 2'b11 : 2'b00;
            2'b11: next_state = train_taken ? 2'b11 : 2'b01;
        endcase
    end
    always @(posedge clk) begin
        if (areset) state <= 2'b01;
        else state <= next_state;
    end
endmodule

