            4'b1000: next_state = in ? 4'b0001 : 4'b1000;
        endcase
    end

    // Derived output logic (combinational)
    always @(*) begin
        case (state)
            4'b0001: out = 1'b0;
            4'b0010: out = 1'b0;
            4'b0100: out = 1'b0;
            4'b1000: out = 1'b1;
        endcase
    end
