            4'b0100: next_state = in ? 4'b0001 : 4'b0100;
            4'b1000: next_state = in ? 4'b0100 : 4'b1000;
            default: next_state = 4'b0001;
        endcase
    end
    // Output logic
    always @(*) begin
        case (next_state)
            4'b0001: out = 1'b0;
            4'b0010: out = 1'b0;
