    assign d = p2c & p2d;
    // 2-input OR gates: f (the second 2-input AND in the functional
    // equivalent), and g (the functional equivalent's third AND, OR pair).
    assign e = a | b;
    assign f = c | d;
    // The final OR gate in the functional equivalent.
    assign p1y = e | f;
    // The second output of the functional equivalent (the third AND, OR pair).
    assign p2y = p2a & p2b;
