module TopModule (
    input  clk,
    input  reset,
    output shift_ena
);
    reg [1:0] state;
    reg [1:0] next_state;
    wire pattern_detected;
    reg [1:0] counter;
    wire counter_max;
    wire shift_ena_i;

    // The pattern we're looking for: 0110 (decimal 6).
    assign pattern_detected = ({shift_ena_i, counter[0]} == 2'b01);

    // Increment the counter if the pattern was detected, or reset it if not.
    always @(posedge clk) begin
        if (pattern_detected) counter <= counter + 2'd1;
        else counter <= 2'd0;
    end

    // Set the maximum value of the counter. This is the final stage in the
    // shift register, so we shift one more cycle.
    assign counter_max = (counter == 2'd3);

    // Next state logic. The state transitions directly to the final stage
    // if the pattern was detected, or to the first stage if not.
    always @* begin
        case (state)
            2'd0: next_state = pattern_detected ? 2'd3 : 2'd1;
            2'd1: next_state = pattern_detected ? 2'd3 : 2'd2;
            2'd2: next_state = pattern_detected ? 2'd3 : 2'd0;
            2'd3: next_state = 2'd3;
            default: next_state = 2'd0;
        endcase
    end

    // Sequential logic for the state register.
    always @(posedge clk) begin
        if (reset) state <= 2'd0;
        else state <= next_state;
    end

    // Combinational logic for shift_ena. The shift register is enabled when
    // the state is in the final stage.
    assign shift_ena_i = (state == 2'd3);

    // The actual shift register is implemented as a chain of registers, with
    // shift_ena applied to the first one.
    reg [31:0] chain [0:3];
    always @(posedge clk) begin
        if (reset) chain[0] <= 32'd0;
        else if (shift_ena_i) chain[0] <= {chain[1][23:0], chain[1][31:24]};
        chain[1] <= chain[2];
        chain[2] <= chain[3];
        chain[3] <= 32'd1;
    end

    assign shift_ena = shift_ena_i;
endmodule

