module TopModule (
    input  [15:0] a,
    input  [15:0] b,
    input  [15:0] c,
    input  [15:0] d,
    input  [15:0] e,
    input  [15:0] f,
    input  [15:0] g,
    input  [15:0] h,
    input  [15:0] i,
    input  [ 3:0] sel,
    output [15:0] out
);
    // The AND-gate-per-input part of the multiplexer: for each input, AND
    // together a single 16-bit wire with a single 16-bit 'enable' input. The
    // result is a 16-bit wire that is high iff the input should be selected.
    wire [15:0] a_en = 16'hFFFF & (16'h0001 << sel);
    wire [15:0] b_en = 16'hFFFF & (16'h0002 << sel);
    wire [15:0] c_en = 16'hFFFF & (16'h0004 << sel);
    wire [15:0] d_en = 16'hFFFF & (16'h0008 << sel);
    wire [15:0] e_en = 16'hFFFF & (16'h0010 << sel);
    wire [15:0] f_en = 16'hFFFF & (16'h0020 << sel);
    wire [15:0] g_en = 16'hFFFF & (16'h0040 << sel);
    wire [15:0] h_en = 16'hFFFF & (16'h0080 << sel);
    wire [15:0] i_en = 16'hFFFF & (16'h0100 << sel);
    // The OR-gate-over-inputs part: take the OR of all the individual
    // 16-bit wires (which are high iff the corresponding input should be
    // selected) to give a single 16-bit output.
    assign out = a_en & a | b_en & b | c_en & c | d_en & d | e_en & e | f_en & f | g_en & g | h_en & h | i_en & i;
endmodule

