    input  [1:0] state,
    output [1:0] next_state,
    output out
);
    // Define the 2-bit state abbreviations inline to make the state transition
    // function a bit more readable.
    localparam A = 2'b00;
    localparam B = 2'b01;
    localparam C = 2'b10;
    localparam D = 2'b11;

    // Define the state transition function. Given the current state and the
    // input, compute the next state and output. Inline this as a combinational
    // function (no assign or always @(*) syntax) to go back to strictly
    // combinational (no register-to-register path) style.
    function [1:0] transit(input [1:0] cur_state, input in);
        case (cur_state)
            A: begin if (in) return B; else return A; end
            B: begin if (in) return B; else return C; end
            C: begin if (in) return D; else return A; end
            D: begin if (in) return B; else return C; end
            default: $display("Invalid state: %d", cur_state);
        endcase
    endfunction

    // Compute the next state and output in the same function (no extra
    // combinational path).
    assign {next_state, out} = transit(state, in);
