module fifo_controller #(
    parameter FIFO_WD = 32,
    parameter FIFO_DEPTH = 16
) (
    input clk,
    input rst_n,
    input [FIFO_WD-1:0] data_in,
    input push,
    input pop,
    output [FIFO_WD-1:0] data_out,
    output full,
    output empty,
    output reg [$clog2(FIFO_DEPTH)-1:0] rd_addr,
    output reg [$clog2(FIFO_DEPTH)-1:0] wr_addr
);

    reg [FIFO_WD-1:0] mem [FIFO_DEPTH-1:0];
    reg [$clog2(FIFO_DEPTH)-1:0] next_rd_addr;
    reg [$clog2(FIFO_DEPTH)-1:0] next_wr_addr;

    always @(posedge clk) begin
        if (rst_n == 1'b0) begin
            rd_addr <= 0;
            wr_addr <= 0;
        end else begin
            rd_addr <= next_rd_addr;
            wr_addr <= next_wr_addr;
        end
    end

    always @(*) begin
        if (push && !full) next_wr_addr = wr_addr + 1;
        else next_wr_addr = wr_addr;
        if (pop && !empty) next_rd_addr = rd_addr + 1;
        else next_rd_addr = rd_addr;
    end

    wire full = (next_wr_addr == next_rd_addr) && push;
    wire empty = next_rd_addr == next_wr_addr;

    always @(posedge clk) begin
        if (push && !full) mem[wr_addr] <= data_in;
    end

    assign data_out = mem[rd_addr];

endmodule

