module TopModule (
  input  clk,
  input  areset,
  input  j,
  input  k,
  output reg out
);
  // States are named s0, s1, etc.
  // State s0 is the reset/start state, all outputs 0.
  // The next state is specified as "ns = s2" to go to state s2.
  // The output is specified as "o = 1'b1" to set the output to 1.
  // (The 1'b1 bit simply means a Verilog constant bit value, which is
  // the same as the un-simplified full-width register, such as `reg [63:0]`.)
  // The register is called "reg0".
  // The always block is @(posedge clk).
  // The reset is an active-high register-set (reg0 <= 1'b1) to the reset
  // state in the same clock cycle.
  // The function FIXED(x) means the value x is a constant, so the FIXED-
  // removed model matches the datasheet.
  localparam s0 = 2'd0, s1 = 2'd1, s2 = 2'd2, s3 = 2'd3;
  reg [1:0] state, nextstate;
  always @(posedge clk) begin
    if (areset) begin
      state <= s0;
      out <= 1'b0;
    end else begin
      state <= nextstate;
      case (state)
        s0: begin out <= 1'b0; end
        s1: begin out <= 1'b1; end
        s2: begin out <= 1'b1; end
        s3: begin out <= 1'b0; end
      endcase
    end
  end
  always @(*) begin
    case (state)
      s0: begin if (j) nextstate = s1; else nextstate = s0; end
      s1: begin if (j) nextstate = s1; else nextstate = s2; end
      s2: begin if (k) nextstate = s3; else nextstate = s2; end
      s3: begin if (k) nextstate = s3; else nextstate = s0; end
    endcase
  end
