        next_state = 2'd1;
        walk_left = 1'b1;
      end
      2'd1: begin
        if (bump_right) next_state = 2'd0;
        if (bump_left) next_state = 2'd2;
        walk_right = 1'b1;
      end
      2'd2: begin
        next_state = 2'd1;
        walk_left = 1'b1;
      end
    endcase
  end
endmodule

module LemmingFSM (
