module LemmingFSM(clk, areset, bump_left, bump_right, walk_left, walk_right);
  input clk;
  input areset;
  input bump_left;
  input bump_right;
  output walk_left;
  output walk_right;
  reg [1:0] state;
  always @(posedge clk) begin
    if (areset) state <= 2'd0;
    else case (state)
      2'd0: begin state <= 2'd1; walk_left <= 1; walk_right <= 0; end
      2'd1: begin
        if (bump_left) begin state <= 2'd0; walk_left <= 0; walk_right <= 1; end
        else if (bump_right) begin state <= 2'd2; walk_left <= 1; walk_right <= 0; end
        else begin state <= 2'd1; walk_left <= 1; walk_right <= 0; end
      end
      2'd2: begin
        if (bump_right) begin state <= 2'd1; walk_left <= 1; walk_right <= 0; end
        else if (bump_left) begin state <= 2'd3; walk_left <= 0; walk_right <= 1; end
        else begin state <= 2'd2; walk_left <= 0; walk_right <= 1; end
      end
      2'd3: begin
        if (bump_left) begin state <= 2'd2; walk_left <= 0; walk_right <= 1; end
        else if (bump_right) begin state <= 2'd0; walk_left <= 1; walk_right <= 0; end
        else begin state <= 2'd3; walk_left <= 0; walk_right <= 1; end
      end
    endcase
  end
endmodule

module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    output reg walk_left,
    output reg walk_right
);
    // Internal registers of the FSM, one per state.
    reg [0:0] state_0;
    reg [0:0] state_1;
    // The next state of the FSM is a function of the current state and
    // the inputs.
    always @(*) begin
        state_0 = 1'b1;
        state_1 = 1'b0;
        if (bump_left) state_0 = 1'b0;
        if (bump_right) state_0 = 1'b1;
    end
    // The output of the FSM is a function of the current state.
    assign walk_left = state_0;
    assign walk_right = state_1;
    // Synchronous reset of the FSM.
    always @(posedge clk) begin
        if (areset) begin
            state_0 <= 1'b1;
            state_1 <= 1'b0;
        end else begin
            state_0 <= state_0;
            state_1 <= state_1;
        end
    end
endmodule

module lemming_fsm(input clk, input areset, input bump_left, input bump_right, output reg walk_left, output reg walk_right);
    reg [1:0] state, next_state;
    parameter LEFT = 2'b00, RIGHT = 2'b01;
    always @(*) begin
        case (state)
            LEFT: next_state = bump_right ? RIGHT : LEFT;
            RIGHT: next_state = bump_left ? LEFT : RIGHT;
            default: next_state = LEFT;
        endcase
    end
    always @(posedge clk) begin
        if (areset) state <= LEFT;
        else state <= next_state;
    end
    assign walk_left = (state == LEFT);
    assign walk_right = (state == RIGHT);
endmodule

module TopModule(input clk, input areset, input bump_left, input bump_right, output reg walk_left, output reg walk_right);
    reg [1:0] state;
    always @(posedge clk) begin
        if (areset) state <= 2'b00;
        else case (state)
            2'b00: begin walk_left <= 1; walk_right <= 0; state <= bump_left ? 2'b10 : 2'b00; end
            2'b01: begin walk_left <= 0; walk_right <= 1; state <= bump_right ? 2'b00 : 2'b01; end
            2'b10: begin walk_left <= 1; walk_right <= 0; state <= bump_left ? 2'b10 : 2'b00; end
            2'b11: begin walk_left <= 0; walk_right <= 1; state <= bump_right ? 2'b00 : 2'b01; end
        endcase
    end
endmodule

module TopModule(
  input  clk,
  input  areset,
  input  bump_left,
  input  bump_right,
  output walk_left,
  output walk_right
);
  reg [1:0] state;
  always @(posedge clk) begin
    if (areset) state <= 2'b00;
    else begin
      case (state)
        2'b00: state <= bump_left ? 2'b10 : (bump_right ? 2'b01 : 2'b00);
        2'b01: state <= bump_left ? 2'b10 : (bump_right ? 2'b00 : 2'b01);
        2'b10: state <= bump_left ? 2'b00 : (bump_right ? 2'b01 : 2'b10);
        2'b11: state <= bump_left ? 2'b00 : (bump_right ? 2'b10 : 2'b11);
      endcase
    end
  end
  assign walk_left = (state == 2'b00) || (state == 2'b11);
  assign walk_right = (state == 2'b01) || (state == 2'b10);
endmodule

module TopModule(
    input  clk,
    input  reset,
    input  [7:0] in,
    output done);
    reg [2:0] count;
    reg [7:0] bytes [0:2];
    reg [1:0] state;
    reg done_reg;
    always @(*) begin
        count = (state == 2 && in[3] == 1) ? 0 : (state != 0 ? count + 1 : 0);
        bytes = (state == 0) ? {bytes[1], bytes[2], in} : bytes;
        state = (state == 0 && in[3] == 1) ? 1 : (state == 1) ? 2 : 0;
        done_reg = (state == 0) ? 1'b0 : (state == 2) ? 1'b1 : done_reg;
    end
    always @(posedge clk) begin
        if (reset) begin
            count <= 3'd0;
            bytes <= '{8'd0, 8'd0, 8'd0};
            state <= 2'd0;
            done_reg <= 1'b0;
        end else begin
            count <= count;
            bytes <= bytes;
            state <= state;
            done_reg <= done_reg;
        end
    end
    assign done = done_reg;
endmodule

