  integer i;
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      for (i = 0; i < 3; i = i + 1) bytes[i] <= 8'b0;
      done <= 1'b0;
    end else begin
      case (state)
        2'b00: if (in[3] == 1'b1) begin state <= 2'b01; bytes[0] <= in; end
        2'b01: begin state <= 2'b10; bytes[1] <= in; end
        2'b10: begin state <= 2'b00; bytes[2] <= in; done <= 1'b1; end
