module PS2FSM(clk, reset, in, done, state_out, byte_out, byte_count_out,
              state_next, byte_next, byte_count_next, next_state);
  input clk, reset;
  input [7:0] in;
  output done;
  output [2:0] state_out, byte_out, byte_count_out;
  input [2:0] state_next, byte_next, byte_count_next;
  input [2:0] next_state;
  reg [2:0] state_reg, state_next;
  reg [7:0] byte_reg, byte_next;
  reg [2:0] byte_count_reg, byte_count_next;
  assign state_out = state_reg;
  assign byte_out = byte_reg;
  assign byte_count_out = byte_count_reg;
  always @(posedge clk) begin
    if (reset) begin
      state_reg <= 3'b000;
      byte_reg <= 8'b00000000;
      byte_count_reg <= 3'b000;
    end else begin
      state_reg <= state_next;
      byte_reg <= byte_next;
      byte_count_reg <= byte_count_next;
    end
  end
  always @(state_reg, byte_reg, byte_count_reg, in) begin
    case (state_reg)
      3'b000: begin // Waiting for the first byte of a new message
        if (in[3] == 1'b1) begin
          state_next = 3'b001;
          byte_next = in;
          byte_count_next = 3'b001;
          done = 1'b0;
        end else begin
          state_next = 3'b000;
          byte_next = byte_reg;
          byte_count_next = byte_count_reg;
          done = 1'b0;
        end
      end
      3'b001: begin // Waiting for the second byte of a message
        state_next = 3'b010;
        byte_next = in;
        byte_count_next = 3'b010;
        done = 1'b0;
      end
      3'b010: begin // Waiting for the third byte of a message
        state_next = 3'b000;
        byte_next = in;
        byte_count_next = 3'b000;
        done = 1'b1;
      end
      default: begin
        state_next = next_state;
        byte_next = byte_reg;
        byte_count_next = byte_count_reg;
        done = 1'b0;
      end
    endcase
  end
endmodule

module FSM (
