    else begin
      case (state)
        5'd0: state = in ? 5'd1 : 5'd0;
        5'd1: state = in ? 5'd2 : 5'd0;
        5'd2: state = in ? 5'd3 : 5'd0;
        5'd3: state = in ? 5'd3 : 5'd0;
      endcase
    end
  end
  always @(*) out = (state == 5'd3);
endmodule

module TopModule(
