        else begin
            case (state)
                2'b00: begin // wait for first byte of a message
                    if (in[3]) begin
                        state <= 2'b01;
                        count <= 3'b001;
                    end
                end
                2'b01: begin // wait for second byte of a message
                    count <= count + 1;
                    if (count == 3'b100) begin
                        state <= 2'b10;
                        count <= 3'b001;
                    end
                end
                2'b10: begin // wait for third byte of a message
                    count <= count + 1;
                    if (count == 3'b111) begin
