module TopModule(clk, reset, in, done);
    input clk, reset;
    input [7:0] in;
    output done;
    reg [2:0] state;
    reg [7:0] bytes [0:2];
    reg [1:0] byte_idx;
    reg [1:0] bit_idx;
    wire [7:0] byte = bytes[byte_idx];
    wire [7:0] byte_next = {byte[6:0], in[0]};
    wire [7:0] byte_next_masked = byte_next & {8{byte_idx == 2}};
    wire done_byte = bit_idx == 7;
    wire done_message = done_byte && byte_next_masked == 8'hfa;
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            byte_idx <= 2'b00;
            bit_idx <= 3'b000;
        end else begin
            case (state)
                3'b000: begin // Wait for first byte with bit 3 set.
                    if (in[3]) begin
                        state <= 3'b001;
                        byte_idx <= 2'b00;
                        bit_idx <= 3'b000;
                    end
                end
                3'b001: begin // Receive the first byte of the message.
                    bytes[byte_idx] <= in;
                    byte_idx <= byte_idx + 1;
                    bit_idx <= bit_idx + 1;
                    if (done_byte) begin
                        state <= 3'b010;
                        byte_idx <= 2'b01;
                        bit_idx <= 3'b000;
                    end
                end
                3'b010: begin // Receive the second byte of the message.
                    bytes[byte_idx] <= in;
                    byte_idx <= byte_idx + 1;
                    bit_idx <= bit_idx + 1;
                    if (done_byte) begin
                        state <= 3'b011;
                        byte_idx <= 2'b10;
                        bit_idx <= 3'b000;
                    end
                end
                3'b011: begin // Receive the third byte of the message.
                    bytes[byte_idx] <= in;
                    byte_idx <= byte_idx + 1;
                    bit_idx <= bit_idx + 1;
                    if (done_message) begin
                        state <= 3'b000;
                        byte_idx <= 2'b00;
                        bit_idx <= 3'b000;
                    end else if (done_byte) begin
                        state <= 3'b011;
                        byte_idx <= 2'b11;
                        bit_idx <= 3'b000;
                    end
                end
            endcase
        end
    end
    assign done = state == 3'b000;
endmodule

// One-bit register for each FSM state. We use registers to separate each
// stage in the pipeline.
reg [2:0] state;
reg [7:0] bytecnt;
reg [7:0] bytes [0:2];

// The FSM is a simple 3-stage pipeline, with the stages implemented as
// separate registers: stage 0 takes the raw byte stream, stage 1 checks
// that it's the first byte of a message (the 3rd bit is 1), stage 2 checks
// that the message consists of 3 bytes.
always @(posedge clk) begin
    if (reset) begin
        state <= 3'd0;
        bytecnt <= 8'd0;
        bytes[0] <= 8'd0;
        bytes[1] <= 8'd0;
        bytes[2] <= 8'd0;
    end else begin
        case (state)
            3'd0: begin // Stage 0: raw byte stream
                bytes[0] <= in;
                state <= 3'd1;
            end
            3'd1: begin // Stage 1: is the first byte of a message?
                if (bytes[0][3]) begin
                    bytes[1] <= in;
                    state <= 3'd2;
                end
                bytecnt <= bytecnt + 1;
            end
            3'd2: begin // Stage 2: is the message a triplet?
                bytes[2] <= in;
                if (bytecnt == 7) begin
                    state <= 3'd0;
                    bytecnt <= 8'd0;
                    done <= 1;
                end else begin
                    bytecnt <= bytecnt + 1;
                    state <= 3'd1;
                end
            end
        endcase
    end
end
endmodule

module TopModule(
    input  clk,
    input  aresetn,
    input  x,
    output z
);
    reg [1:0] state, next_state;
    wire [1:0] next_state_raw;
    reg z_reg;
    assign z = z_reg;
    always @(*) begin
        case (state)
            2'd0: next_state_raw = x ? 2'd1 : 2'd0;
            2'd1: next_state_raw = x ? 2'd2 : 2'd0;
            2'd2: next_state_raw = x ? 2'd0 : 2'd0;
        endcase
    end
    always @(posedge clk) begin
        if (~aresetn) begin
            state <= 2'd0;
            z_reg <= 1'd0;
        end else begin
            state <= next_state;
            z_reg <= (state == 2'd2);
        end
    end
    assign next_state = next_state_raw;
endmodule

module TopModule (
    input  clk,
    input  aresetn,
    input  x,
    output z
);
    reg [1:0] state;
    wire [1:0] next_state;
    wire z_comb;
    // State transition logic.
    always @(posedge clk) begin
        if (!aresetn) state <= 2'b00;
        else state <= next_state;
    end
    // Combination of next state and output.
    always @* begin
        case (state)
            2'b00: begin next_state = 2'b01; z_comb = 1'b0; end
            2'b01: begin next_state = 2'b10; z_comb = 1'b0; end
            2'b10: begin next_state = 2'b11; z_comb = 1'b1; end
            2'b11: begin next_state = 2'b00; z_comb = 1'b0; end
        endcase
    end
    // Output delay one clock cycle (a registerless FSM, the equivalent of a
    // registerful FSM with an extra delay on the output).
    reg z_delayed;
    always @(posedge clk) z_delayed <= z_comb;
    assign z = z_delayed;
endmodule

module TopModule (
