        case (state)
            2'b00: begin
                z_reg = 1'b0;
                if (x) next_state = 2'b01;
                else next_state = 2'b00;
            end
            2'b01: begin
                z_reg = 1'b0;
                if (x) next_state = 2'b10;
                else next_state = 2'b00;
            end
            2'b10: begin
                z_reg = 1'b1;
                if (x) next_state = 2'b01;
                else next_state = 2'b00;
            end
            default: begin
                z_reg = 1'b0;
                next_state = 2'b00;
            end
        endcase
    end
    always @(posedge clk) begin
        if (!aresetn) state <= 2'b00;
        else state <= next_state;
    end
    assign z = z_reg;
endmodule

module TopModule(
