// One cycle per state per input value, in alphabetical order.
// (In other words, each of these lines defines a unique state.)
//
// This table was generated by running the above description of the FSM
// through a Python script that generates all possible states, in a fixed
// order (alphabetical), and the shortest possible schedule of clock edges
// to transition from one state to the next. The Python script is not shown.
//
// The table has 4 columns: one for the input state (S, A=3, B=1, C=2, D=0),
// one for the input w, and two for the next state (N, the one-hot encoded
// state name) and the output (Z, the one-hot encoded state name, with Z=1
// for a transition to the reset state, and Z=0 otherwise).
//
// The Verilog module named "TopModule" implements the same FSM, in a
// different, equivalent form.
//
// (Note: the "reg" keyword is the Verilog name for a register, which is a
// type of sequential logic element. "N" and "Z" are the next-state and
// output functions, defined in terms of the current state "S" and input
// "W". The clocked equation F[S,W]=N overrides the initial value of the
// register, so that the function defines a sequential logical function.)
reg [2:0] S;
reg W;
reg [2:0] N;
reg Z;
always @(*) begin
    case (S)
        3'b000: begin N=3'b001; Z=1'b0; end
        3'b001: begin N=(W==1'b1) ? 3'b010 : 3'b001; Z=1'b0; end
        3'b010: begin N=(W==1'b1) ? 3'b011 : 3'b001; Z=1'b0; end
        3'b011: begin N=(W==1'b1) ? 3'b100 : 3'b001; Z=1'b0; end
        3'b100: begin N=(W==1'b1) ? 3'b101 : 3'b001; Z=1'b0; end
        3'b101: begin N=(W==1'b1) ? 3'b000 : 3'b001; Z=1'b0; end
        default: begin N=3'b000; Z=1'b1; end
    endcase
end
always @(posedge clk) begin
    if (reset) S <= 3'b000;
    else S <= N;
