// One-hot state encoding:
//
//   A = 3'b000
//   B = 3'b001
//   C = 3'b010
//   D = 3'b011
//   E = 3'b100
//   F = 3'b101
//   G = 3'b110
//   H = 3'b111
//
// The FSM moves from state to state following the specification in the
// adjacent list. The first number is the current state, and the second
// number is the next state given inputs (s, w).
reg [2:0] state, next_state;
always @(*) begin
  case (state)
    3'b000: next_state = s ? 3'b001 : 3'b000;
    3'b001: next_state = s ? 3'b010 : w ? 3'b011 : 3'b001;
    3'b010: next_state = s ? 3'b011 : w ? 3'b100 : 3'b010;
    3'b011: next_state = s ? 3'b100 : w ? 3'b101 : 3'b011;
    3'b100: next_state = s ? 3'b101 : w ? 3'b110 : 3'b100;
    3'b101: next_state = s ? 3'b110 : w ? 3'b111 : 3'b101;
    3'b110: next_state = s ? 3'b111 : 3'b000;
    3'b111: next_state = 3'b000;
    default: next_state = 3'bx;
  endcase
end

// Register the state, always on the clock, with asynchronous reset.
reg [2:0] state_r;
always @(posedge clk) begin
  if (reset) state_r <= 3'b000;
  else state_r <= next_state;
end

// Assign the output based on the current state.
reg z_r;
always @(*) begin
  case (state_r)
    3'b000: z_r = 1'b0;
    3'b001: z_r = 1'b0;
    3'b010: z_r = 1'b0;
    3'b011: z_r = 1'b0;
    3'b100: z_r = 1'b0;
    3'b101: z_r = 1'b0;
    3'b110: z_r = 1'b1;
    3'b111: z_r = 1'b0;
    default: z_r = 1'bx;
  endcase
end

// Wire up the registers to the outputs.
wire z = z_r;
endmodule

