module FSM(clk, reset, s, w, z);
  input clk, reset, s, w;
  output z;
  reg [2:0] state;
  reg [1:0] count;
  reg next_count;
  reg next_state;
  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b000;
      count <= 2'b00;
    end else begin
      state <= next_state;
      count <= next_count;
    end
  end
  always @* begin
    next_state = state;
    next_count = count;
    case (state)
      3'b000: begin // A state
        if (s) begin
          next_state = 3'b001;
          next_count = 2'b00;
        end
      end
      3'b001: begin // B state
        next_count = count + 1;
        if (count == 2'b10) begin
          next_state = 3'b010;
        end
      end
      3'b010: begin // C state
        if (w) begin
          next_count = count + 1;
        end
        if (count == 2'b11) begin
          next_state = 3'b000;
        end
      end
    endcase
  end
  assign z = (state == 3'b010 && count == 2'b10);
endmodule

