  reg [7:0] data;
  always @(posedge clk) begin
    if (reset) begin
      state <= 3'b000;
      data <= 8'd0;
      done <= 1'b0;
    end else begin
      case (state)
        3'b000: begin // Wait for start bit.
          if (in) state <= 3'b001;
        end
        3'b001: begin // Wait for data bits.
          data <= {in, data[7:1]};
          if (&~|data) state <= 3'b010; // Go to next state if all bits received.
        end
        3'b010: begin // Wait for stop bit.
          if (~in) state <= 3'b011;
        end
        3'b011: begin // Go to idle state and set done flag.
          done <= 1'b1;
          state <= 3'b000;
        end
      endcase
    end
  end
endmodule

