      data <= 8'b0;
      bit_count <= 3'b000;
      done <= 1'b0;
    end else begin
      case (state)
        3'b000: begin // idle - wait for a start bit
          if (in == 1'b0) begin
            state <= 3'b001;
            bit_count <= 3'b000;
          end
        end
        3'b001: begin // start bit received, wait for data bits
