      3'b011: state <= w ? 3'b100 : 3'b001;
      3'b100: state <= w ? 3'b101 : 3'b001;
      3'b101: state <= w ? 3'b101 : 3'b110;
      3'b110: state <= w ? 3'b011 : 3'b001;
      default: state <= 3'b001;
    endcase
  end
  always @(state) begin
    case (state)
      3'b001: z = 1'b0;
      3'b010: z = 1'b0;
      3'b011: z = 1'b0;
      3'b100: z = 1'b0;
      3'b101: z = 1'b1;
      3'b110: z = 1'b0;
      default: z = 1'b0;
    endcase
  end
endmodule

module FSM(input clk, input resetn, input x, input y, output reg f, output reg g);
    reg [1:0] state;
    reg [1:0] x_reg;
    reg [1:0] y_delay;
    always @(posedge clk) begin
        if (!resetn) begin
            state <= 2'b00;
            x_reg <= 2'b00;
            y_delay <= 2'b00;
            f <= 1'b1;
            g <= 1'b0;
        end else begin
            case (state)
                2'b00: begin
                    f <= 1'b1;
                    g <= 1'b0;
                    if (x) begin
                        x_reg <= 2'b01;
                        state <= 2'b01;
                    end else begin
                        x_reg <= 2'b00;
                    end
                end
                2'b01: begin
                    f <= 1'b0;
                    g <= 1'b0;
                    if (x) begin
                        x_reg <= 2'b10;
                        state <= 2'b10;
                    end else begin
                        x_reg <= 2'b00;
                        state <= 2'b00;
                    end
                end
                2'b10: begin
                    f <= 1'b0;
                    g <= 1'b0;
                    if (x) begin
                        x_reg <= 2'b11;
                        state <= 2'b11;
                    end else begin
                        x_reg <= 2'b00;
                        state <= 2'b00;
                    end
                end
                2'b11: begin
                    f <= 1'b0;
                    g <= 1'b1;
                    if (x) begin
                        x_reg <= 2'b11;
                    end else begin
                        x_reg <= 2'b00;
                        state <= 2'b00;
                    end
                end
            endcase
            y_delay <= y;
            if (y_delay && !y) state <= 2'b00;
        end
    end
