module TopModule(
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output reg f,
    output reg g
);
    // Internal FSM encoding the above description.
    reg [1:0] state;
    always @(posedge clk) begin
        if (!resetn) begin
            state <= 2'b00;
            f <= 1;
            g <= 0;
        end else begin
            case (state)
                2'b00: begin
                    f <= 1;
                    g <= 0;
                    if (x == 1 && x == #1 x && x == #2 x && x == #3 x) begin
                        state <= 2'b01;
                        g <= 1;
                    end
                end
                2'b01: begin
                    f <= 1;
                    g <= 1;
                    if (y == 1 && y == #1 y) g <= 1;
                    else state <= 2'b00;
                end
                default: begin
                    f <= 1;
                    g <= 0;
                end
            endcase
        end
    end
endmodule

module motor_fsm (
    input clk,
    input resetn,
    input x,
    input y,
    output reg f,
    output reg g
);
    parameter A = 2'b00, B = 2'b01, C = 2'b10, D = 2'b11;
    reg [1:0] state, next_state;
    reg [2:0] x_count;
    reg [1:0] y_count;

    always @(*) begin
        case (state)
            A: next_state = B;
            B: next_state = (x_count == 3) ? C : B;
            C: next_state = (y_count == 1) ? D : C;
            D: next_state = (y_count == 0) ? C : D;
        endcase
    end

    always @(posedge clk) begin
        if (!resetn) begin
            state <= A;
            f <= 1;
            g <= 0;
            x_count <= 0;
            y_count <= 0;
        end else begin
            state <= next_state;
            f <= 0;
            g <= 0;
            x_count <= 0;
            y_count <= 0;
            if (state == B) x_count <= x_count + 1;
            if (state == C) begin
                g <= 1;
                y_count <= y;
            end
            if (state == D) begin
                g <= 0;
                y_count <= 0;
            end
        end
    end
endmodule

module FSM(clk, resetn, x, y, f, g);
  input clk, resetn, x, y;
  output reg f, g;
  reg [1:0] state;
  reg [1:0] x_count;
  reg [1:0] y_count;
  always @(posedge clk) begin
    if (!resetn) begin
      state <= 2'b00;
      f <= 1'b0;
      g <= 1'b0;
      x_count <= 2'b00;
      y_count <= 2'b00;
    end else begin
      case (state)
        2'b00: begin
          f <= 1'b1;
          g <= 1'bx;
          x_count <= 2'b00;
          y_count <= 2'b00;
          if (x) x_count <= 2'b01;
          state <= 2'b01;
        end
        2'b01: begin
          f <= 1'b0;
          g <= 1'bx;
          x_count <= x_count + 2'b01;
          y_count <= 2'b00;
          if (x && x_count == 2'b11) begin
            g <= 1'b1;
            state <= 2'b10;
          end else if (!x) begin
            x_count <= 2'b00;
          end
        end
        2'b10: begin
          f <= 1'b0;
          g <= 1'b1;
          x_count <= 2'b00;
          y_count <= y_count + 2'b01;
          if (!y) begin
            g <= 1'b0;
            state <= 2'b00;
          end else if (y_count == 2'b10) begin
            g <= 1'b0;
            state <= 2'b00;
          end
        end
      endcase
    end
  end
endmodule

module TopModule(
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output reg f,
    output reg g
);
    reg [1:0] state;
    reg [1:0] x_history;
    reg [1:0] y_history;
    integer i;

    always @(posedge clk) begin
        if (!resetn) begin
            state <= 2'b00;
            f <= 1'b0;
            g <= 1'b0;
            x_history <= 2'b00;
            y_history <= 2'b00;
        end else begin
            case (state)
                2'b00: begin // Beginning state. Set f to 1 and go to state 1.
                    f <= 1'b1;
                    g <= 1'b0;
                    state <= 2'b01;
                end
                2'b01: begin // Go to state 2 after one clock cycle.
                    f <= 1'b0;
                    g <= 1'b0;
                    state <= 2'b10;
                end
                2'b10: begin // Monitor x. If it produces the values 1, 0, 1 in
                            // three successive clock cycles, go to state 3.
                    x_history <= {x_history[0], x};
                    if (x_history == 2'b101) begin
                        g <= 1'b1;
                        state <= 2'b11;
                    end
                end
                2'b11: begin // Monitor y. If it stays at 1 for at most two
                            // clock cycles, maintain g = 1. Otherwise, set g
                            // = 0.
                    y_history <= {y_history[0], y};
                    if (y == 1'b1) begin
                        g <= 1'b1;
                    end else if (y_history == 2'b00) begin
                        g <= 1'b0;
                        state <= 2'b00;
                    end
                end
            endcase
        end
    end
endmodule

module FSM(clk, resetn, x, y, f, g);
    input clk, resetn, x, y;
    output reg f, g;
    reg [1:0] state;
    reg [2:0] x_count;
    reg [1:0] y_count;

    always @(posedge clk) begin
        if (!resetn) begin
            state <= 2'b00;
            f <= 1'b0;
            g <= 1'b0;
            x_count <= 3'b000;
            y_count <= 2'b00;
        end else begin
            case (state)
                2'b00: begin // Beginning state, set f to 1
                    f <= 1'b1;
                    g <= 1'b0;
                    x_count <= 3'b000;
                    y_count <= 2'b00;
                    if (x) x_count <= 3'b001;
                    state <= 2'b01;
                end
                2'b01: begin // Monitor x, set g when x is 1, 0, 1
                    f <= 1'b1;
                    if (x) x_count <= x_count + 1;
                    if (x_count == 3'b011) begin
                        g <= 1'b1;
                        state <= 2'b10;
                    end
                end
                2'b10: begin // Monitor y, set g to 0 if y is not 1
                    g <= 1'b1;
                    if (!y) g <= 1'b0;
                    if (y) y_count <= 2'b00;
                    else y_count <= y_count + 1;
                    if (y_count == 2'b10) g <= 1'b0;
                end
            endcase
        end
    end
endmodule

module FSM(clk, resetn, x, y, f, g);
  input clk, resetn, x, y;
