  always @(posedge clk) begin
    if (!resetn) begin
      state <= 2'b00;
      f <= 1;
      g <= 0;
    end else begin
      case (state)
        2'b00: begin // beginning state
          f <= 1;
          g <= 0;
          if (x == 1 && x && x == y && y) state <= 2'b01;
        end
        2'b01: begin // after 1 0 1 in three cycles
          f <= 0;
          g <= 1;
          if (y == 1) state <= 2'b10;
        end
        2'b10: begin // after g = 1 and y = 1
          f <= 0;
          g <= 1;
          if (y != 1) state <= 2'b00;
        end
      endcase
    end
  end
endmodule

module FSM(clk, resetn, x, y, f, g);
