    if (!resetn) begin
      f <= 0; g <= 0; state <= 2'b00; count <= 3'b000;
    end else begin
      case (state)
        2'b00: begin f <= 1; state <= 2'b01; count <= 3'b000; end
        2'b01: begin count <= count + 1; if (count == 3'b011 && x == 1) state <= 2'b10; end
        2'b10: begin g <= 1; if (y == 1) count <= 3'b000; else state <= 2'b11; end
        2'b11: begin g <= 0; if (y == 1) count <= 3'b000; end
      endcase
    end
  end
endmodule

module FSM (
    input clk,
    input resetn,
    input x,
    input y,
    output reg f,
    output reg g
);
    // Define the states of the FSM
    parameter [1:0] STATE_A = 2'b00, STATE_B = 2'b01, STATE_C = 2'b10, STATE_D = 2'b11;
    reg [1:0] state;
    reg [1:0] x_shift_reg;
    integer i;

    // The FSM logic
    always @(posedge clk) begin
        if (!resetn) begin
            state <= STATE_A;
            f <= 1'b0;
            g <= 1'b0;
            x_shift_reg <= 2'b00;
        end else begin
            case (state)
                STATE_A: begin
                    f <= 1'b1;
                    g <= 1'b0;
                    x_shift_reg <= 2'b00;
                    state <= STATE_B;
                end
                STATE_B: begin
                    f <= 1'b0;
                    g <= 1'b1;
                    x_shift_reg <= {x_shift_reg[0], x};
                    if (x_shift_reg == 2'b111) begin
                        state <= STATE_C;
                    end
                end
                STATE_C: begin
                    f <= 1'b0;
                    g <= 1'b1;
                    x_shift_reg <= {x_shift_reg[0], x};
                    for (i = 0; i < 3; i = i + 1) begin
                        if (y == 1'b1) begin
                            state <= STATE_C;
                        end else begin
                            state <= STATE_D;
                        end
                    end
                end
                STATE_D: begin
                    f <= 1'b0;
                    g <= 1'b0;
                    x_shift_reg <= {x_shift_reg[0], x};
                end
            endcase
        end
    end
endmodule

module TopModule(input clk, input resetn, input x, input y, output reg f, output reg g);
    reg [1:0] state;
    reg [1:0] x_reg;
    reg [2:0] y_delay;
    always @(posedge clk) begin
        if (!resetn) begin
            state <= 2'b00;
            x_reg <= 2'b00;
            y_delay <= 3'b000;
            f <= 1'b1;
            g <= 1'b0;
        end else begin
            case (state)
                2'b00: begin // Beginning state. Set f to 1 and go to state 1.
                    f <= 1'b1;
                    g <= 1'b0;
                    state <= 2'b01;
                end
                2'b01: begin // Set f to 0 and go to state 2.
                    f <= 1'b0;
                    g <= 1'b0;
                    state <= 2'b10;
                end
                2'b10: begin // Monitor x.
                    x_reg <= {x_reg[0], x};
                    if (x_reg == 2'b111) begin
                        // x has produced the values 1, 0, 1 in three
                        // consecutive clock cycles. Set g to 1 and go to
                        // state 3.
                        g <= 1'b1;
                        state <= 2'b11;
                    end else begin
                        // Don't change g. Stay in state 2.
                        g <= 1'b0;
                        state <= 2'b10;
                    end
                end
                2'b11: begin // Monitor y and go back to state 2 if y is 0.
                    y_delay <= {y_delay[1:0], y};
                    if (y_delay[2] == 1'b1) begin
                        // y has been 1 within at most two clock cycles.
                        // Stay in state 3.
                        g <= 1'b1;
                        state <= 2'b11;
                    end else begin
                        // y has been 0 within at most two clock cycles.
                        // Set g to 0 and go back to state 2.
                        g <= 1'b0;
                        state <= 2'b10;
                    end
                end
            endcase
        end
    end
endmodule

module TopModule(
