                    end else begin
                        state <= 3'b000;
                        count <= 3'b000;
                    end
                end
                3'b011: begin
                    if (in) begin
                        state <= 3'b100;
                        count <= 3'b100;
                    end else begin
                        state <= 3'b000;
                        count <= 3'b000;
                    end
                end
