                        count <= 3'b111;
                    end else begin
                        state <= 3'b000;
                        count <= 3'b000;
                    end
                end
                3'b111: begin
                    if (in) begin
                        state <= 3'b111;
                        count <= 3'b111;
                    end else begin
                        state <= 3'b000;
                        count <= 3'b000;
                    end
                end
            endcase
            if (count == 3'b011) begin
                disc <= 1'b1;
