                flag <= 1'b0;
            end
            if (count >= 3'b0111) begin
                err <= 1'b1;
            end else begin
                err <= 1'b0;
            end
            if (count == 3'b1110) begin
                count <= 3'b000;
            end else begin
                count <= count + 1;
            end
        end
    end
endmodule

