module TopModule(
    input  clk,
    input  reset,
    input  ena,
    output pm,
    output [7:0] hh,
    output [7:0] mm,
    output [7:0] ss
);
    reg [7:0] hh_nxt, mm_nxt, ss_nxt;
    reg pm_nxt;
    always @(*) begin
        hh_nxt = hh;
        mm_nxt = mm;
        ss_nxt = ss + 1'b1;
        pm_nxt = pm;
        if (ss_nxt == 8'd60) begin
            ss_nxt = 8'd0;
            mm_nxt = mm + 1'b1;
            if (mm_nxt == 8'd60) begin
                mm_nxt = 8'd0;
                hh_nxt = hh + 1'b1;
                if (hh_nxt == 8'd13) begin
                    hh_nxt = 8'd1;
                    pm_nxt = ~pm;
                end
            end
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            hh <= 8'd12;
            mm <= 8'd0;
            ss <= 8'd0;
            pm <= 1'b0;
        end else if (ena) begin
            hh <= hh_nxt;
            mm <= mm_nxt;
            ss <= ss_nxt;
            pm <= pm_nxt;
        end
    end
    // Convert to BCD: one digit per stage, so we only need one register per
    // digit (instead of, e.g., two registers per digit, like in the straight
    // up incrementing counter).
    reg [3:0] h10, h1, m10, m1, s10, s1;
    always @(posedge clk) begin
        if (reset) begin
            h10 <= 4'd1;
            h1 <= 4'd2;
            m10 <= 4'd0;
            m1 <= 4'd0;
            s10 <= 4'd0;
            s1 <= 4'd0;
        end else if (ena) begin
            h10 <= (hh_nxt >= 8'd10) ? 4'd1 : 4'd0;
            h1 <= (hh_nxt >= 8'd10) ? hh_nxt - 8'd10 : hh_nxt;
            m10 <= (mm_nxt >= 8'd10) ? 4'd1 : 4'd0;
            m1 <= (mm_nxt >= 8'd10) ? mm_nxt - 8'd10 : mm_nxt;
            s10 <= (ss_nxt >= 8'd10) ? 4'd1 : 4'd0;
            s1 <= (ss_nxt >= 8'd10) ? ss_nxt - 8'd10 : ss_nxt;
        end
    end
    assign hh = 8'd100 * h10 + 10'd10 * h1 + h1;
    assign mm = 8'd100 * m10 + 10'd10 * m1 + m1;
    assign ss = 8'd100 * s10 + 10'd10 * s1 + s1;
endmodule

module TopModule(input clk, input reset, input ena, output pm, output reg [7:0] hh, output reg [7:0] mm, output reg [7:0] ss);
