        if (reset) begin
            r <= 24'd12000000; h <= 4'd12; m <= 4'd0; s <= 4'd0; ampm <= 1'b0;
        end else if (ena) begin
            r <= r - 24'd1;
            if (r == 24'd0) begin
                r <= 24'd12000000;
                h <= (h == 4'd12) ? 4'd1 : h + 4'd1;
                if (h == 4'd13) h <= 4'd1;
                if ((h == 4'd12) && (ampm == 1'b1)) ampm <= 1'b0;
                if ((h == 4'd1) && (ampm == 1'b0)) ampm <= 1'b1;
                if (h == 4'd12) m <= 4'd0;
                if (h == 4'd1 && m == 4'd0 && s == 4'd0) begin m <= 4'd1; s <= 4'd0; end
