            if (r == 24'd11999999) begin
                m <= (m == 4'd59) ? 4'd0 : m + 4'd1;
                if (m == 4'd0 && (h != 4'd12 || ampm == 1'b0)) s <= 4'd0;
            end
            if (r == 24'd11999999 && m == 4'd59 && h != 4'd12) begin
                s <= s + 4'd1;
            end
        end
    end

    function [7:0] to_bcd; input [3:0] x; begin to_bcd = {4'd0, x} + (4'd0, x >= 4'd10); end endfunction
    assign hh = to_bcd(h);
    assign mm = to_bcd(m);
    assign ss = to_bcd(s);
    assign pm = ampm;
endmodule

