module TopModule(input clk, input areset, input bump_left, input bump_right, input ground, output reg walk_left, output reg walk_right, output reg aaah);
  reg [1:0] state;
  always @(posedge clk) begin
    if (areset) begin
      state <= 2'b00;
      walk_left <= 1'b1;
      walk_right <= 1'b0;
      aaah <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // walking left
          walk_left <= 1'b1;
          walk_right <= 1'b0;
          aaah <= 1'b0;
          if (bump_right) state <= 2'b01;
          else if (ground == 0) state <= 2'b10;
        end
        2'b01: begin // bumped on right, walking right
          walk_left <= 1'b0;
          walk_right <= 1'b1;
          aaah <= 1'b0;
          if (bump_left) state <= 2'b00;
          else if (ground == 0) state <= 2'b10;
        end
        2'b10: begin // falling
          walk_left <= 1'b0;
          walk_right <= 1'b0;
          aaah <= 1'b1;
          if (ground == 1) state <= 2'b00;
        end
      endcase
    end
  end
endmodule

