            2'b01: next_state = bump_right ? 2'b00 : 2'b01;
            2'b10: next_state = bump_right ? 2'b01 : 2'b10;
            2'b11: next_state = bump_left ? 2'b00 : 2'b11;
        endcase
    end
    always @(posedge clk) begin
        if(areset) state <= 2'b00;
        else state <= next_state;
    end
    always @(*) begin
        walk_left = state == 2'b00 || state == 2'b10;
        walk_right = state == 2'b01 || state == 2'b11;
        aaah = ground == 1'b0;
    end
endmodule

module TopModule (
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    input ground,
    output reg walk_left,
    output reg walk_right,
    output reg aaah
);
    // Define the states of the Moore machine.
    parameter S_LEFT = 2'b00;
    parameter S_RIGHT = 2'b01;
    parameter S_FALL = 2'b10;
    // The current state.
    reg [1:0] state = S_LEFT;
    // The next state, computed combinatorially based on the current state
    // and the inputs.
    wire [1:0] next_state;
    assign next_state = (state == S_LEFT) ? ((bump_left && bump_right) ? S_RIGHT : (bump_left ? S_RIGHT : (bump_right ? S_LEFT : S_LEFT))) : ((bump_left && bump_right) ? S_LEFT : (bump_left ? S_LEFT : (bump_right ? S_RIGHT : S_RIGHT)));
    // The outputs, computed combinatorially based on the current state.
    assign walk_left = (state == S_LEFT);
    assign walk_right = (state == S_RIGHT);
    assign aaah = (state == S_FALL);
    // On each clock cycle, go to the next state.
    always @(posedge clk) begin
        if (areset) state <= S_LEFT;
        else state <= next_state;
    end
    // If the ground is gone and it's not falling, start falling.
    always @(posedge clk) begin
        if (ground == 1'b0 && state != S_FALL) state <= S_FALL;
    end
    // If the ground reappears while falling, stop falling and go back to
    // walking in the same direction.
    always @(posedge clk) begin
        if (ground == 1'b1 && state == S_FALL) state <= (walk_left ? S_LEFT : S_RIGHT);
    end
endmodule

module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output reg walk_left,
    output reg walk_right,
    output reg aaah
);
    // The three states of the Moore machine.
    parameter STATE_LEFT = 2'b00;
    parameter STATE_RIGHT = 2'b01;
    parameter STATE_FALLING = 2'b10;
    reg [1:0] state;

    always @(posedge clk) begin
        if (areset) begin
            state <= STATE_LEFT;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
        end else begin
            // Transition to the next state on the positive edge of the clock.
            case (state)
                STATE_LEFT: begin
                    if (bump_left) begin
                        state <= STATE_RIGHT;
                        walk_left <= 0;
                        walk_right <= 1;
                    end else if (bump_right) begin
                        state <= STATE_RIGHT;
                        walk_left <= 0;
                        walk_right <= 1;
                    end else if (!ground) begin
                        state <= STATE_FALLING;
                        walk_left <= 0;
                        walk_right <= 0;
                        aaah <= 1;
                    end
                end
                STATE_RIGHT: begin
                    if (bump_right) begin
                        state <= STATE_LEFT;
                        walk_left <= 1;
                        walk_right <= 0;
                    end else if (bump_left) begin
                        state <= STATE_LEFT;
                        walk_left <= 1;
                        walk_right <= 0;
                    end else if (!ground) begin
                        state <= STATE_FALLING;
                        walk_left <= 0;
                        walk_right <= 0;
                        aaah <= 1;
                    end
                end
                STATE_FALLING: begin
                    if (ground) begin
                        if (bump_left) begin
                            state <= STATE_RIGHT;
                            walk_left <= 0;
                            walk_right <= 1;
                        end else if (bump_right) begin
                            state <= STATE_RIGHT;
                            walk_left <= 0;
                            walk_right <= 1;
                        end else begin
                            state <= STATE_LEFT;
                            walk_left <= 1;
                            walk_right <= 0;
                        end
                        aaah <= 0;
                    end
                end
            endcase
        end
    end
endmodule

module TopModule(clk, areset, bump_left, bump_right, ground, walk_left, walk_right, aaah);
  input clk, areset, bump_left, bump_right, ground;
  output walk_left, walk_right, aaah;
  reg [1:0] state, next_state;
  always @(posedge clk) begin
    if (areset) state <= 2'b00;
    else state <= next_state;
  end
  always @(*) begin
    case (state)
      2'b00: begin // LEFT
        walk_left = 1'b1;
        walk_right = 1'b0;
        aaah = 1'b0;
        if (bump_left) next_state = 2'b10;
        else if (ground) next_state = 2'b00;
        else next_state = 2'b01;
      end
      2'b01: begin // FALLING
        walk_left = 1'b1;
        walk_right = 1'b0;
        aaah = 1'b1;
        if (ground) next_state = 2'b00;
        else next_state = 2'b01;
      end
      2'b10: begin // RIGHT
        walk_left = 1'b0;
        walk_right = 1'b1;
        aaah = 1'b0;
        if (bump_right) next_state = 2'b00;
        else if (ground) next_state = 2'b10;
        else next_state = 2'b11;
      end
      2'b11: begin // FALLING2
        walk_left = 1'b0;
        walk_right = 1'b1;
        aaah = 1'b1;
        if (ground) next_state = 2'b10;
        else next_state = 2'b11;
      end
    endcase
  end
endmodule

module TopModule(
  input  clk,
  input  areset,
  input  bump_left,
  input  bump_right,
  input  ground,
  output walk_left,
  output walk_right,
  output aaah
);
  // The state variable can take one of four values: 0, 1, 2, or 3.
  reg [1:0] state;
  always @(posedge clk) begin
    if (areset) state <= 2'b00;
    else begin
      case (state)
        2'b00: if (bump_left) state <= 2'b01; else if (bump_right) state <= 2'b10; else state <= 2'b00;
        2'b01: if (ground) state <= 2'b00; else state <= 2'b01;
        2'b10: if (ground) state <= 2'b00; else state <= 2'b10;
        2'b11: if (ground) state <= 2'b00; else state <= 2'b11;
      endcase
    end
  end
  // Derive the outputs from the state.
  assign walk_left = (state == 2'b00) || (state == 2'b11);
  assign walk_right = (state == 2'b01) || (state == 2'b10);
  assign aaah = state == 2'b11;
endmodule

module TopModule(clk, areset, bump_left, bump_right, ground, walk_left, walk_right, aaah);
  input clk, areset, bump_left, bump_right, ground;
  output walk_left, walk_right, aaah;
  reg [1:0] state, next_state;
  reg [1:0] bump_delayed1, bump_delayed2;
  wire falling;
  reg falling_delayed1, falling_delayed2;
  reg aaah_pulse;

  // Delay the bump and falling edges by one clock cycle to avoid
  // combinational loop in the state transition function.
  always @(posedge clk) begin
    bump_delayed1 <= bump_left;
    bump_delayed2 <= bump_delayed1;
    falling_delayed1 <= falling;
    falling_delayed2 <= falling_delayed1;
  end

  // State transition function
  always @(*) begin
    if (areset)
      next_state = 2'b00;
    else
      case (state)
        2'b00: if (falling_delayed2) next_state = 2'b00; else next_state = 2'b01;
        2'b01: if (bump_delayed2) next_state = 2'b10; else next_state = 2'b01;
        2'b10: if (bump_delayed2) next_state = 2'b01; else next_state = 2'b10;
        default: next_state = 2'b00;
      endcase
  end

  // Synchronous state register
  always @(posedge clk) begin
    if (areset)
      state <= 2'b00;
    else
      state <= next_state;
  end

  // Output functions
  assign walk_left = (state == 2'b01);
  assign walk_right = (state == 2'b10);
  assign falling = (ground == 1'b0);
  assign aaah = aaah_pulse;

  // aaah pulse: a one-clock long pulse that goes high for one clock
  // cycle every time falling goes high. This is a simple way to make
  // the Lemming say "aaah!" when it falls.
  always @(posedge clk) begin
    if (falling)
      aaah_pulse <= 1'b1;
    else if (aaah_pulse)
      aaah_pulse <= 1'b0;
  end
endmodule

module TopModule(input clk, input areset, input bump_left, input bump_right, input ground,
                 output reg walk_left, output reg walk_right, output reg aaah);
    reg [1:0] state;
    always @(posedge clk) begin
        if (areset) state <= 2'b00;
        else begin
            case (state)
                2'b00: begin // walking left
                    walk_left <= 1;
                    walk_right <= 0;
                    aaah <= 0;
                    if (bump_right) state <= 2'b01; // bumped right -> walk right
                    else if (ground == 0) state <= 2'b10; // fell -> falling
                end
                2'b01: begin // walking right
                    walk_left <= 0;
                    walk_right <= 1;
                    aaah <= 0;
                    if (bump_left) state <= 2'b00; // bumped left -> walk left
                    else if (ground == 0) state <= 2'b10; // fell -> falling
                end
                2'b10: begin // falling
                    walk_left <= 0;
                    walk_right <= 0;
                    aaah <= 1;
                    if (ground == 1) state <= 2'b00; // ground reappeared -> walk left
                end
            endcase
        end
    end
endmodule

module TopModule(clk, areset, bump_left, bump_right, ground, walk_left, walk_right, aaah);
  input clk, areset, bump_left, bump_right, ground;
  output walk_left, walk_right, aaah;
  reg [1:0] state, nextstate;
  always @(*) begin
    case (state)
      2'd0: nextstate = bump_left ? 2'd1 : bump_right ? 2'd2 : 2'd0;
      2'd1: nextstate = bump_left ? 2'd1 : bump_right ? 2'd2 : 2'd0;
      2'd2: nextstate = bump_left ? 2'd1 : bump_right ? 2'd2 : 2'd0;
      default: nextstate = 2'd0;
    endcase
  end

  always @(posedge clk) begin
    if (areset) state <= 2'd0;
    else state <= nextstate;
  end

  assign walk_left = state == 2'd0;
  assign walk_right = state == 2'd1;
  assign aaah = ground == 1'b0;
endmodule

module TopModule(clk, areset, bump_left, bump_right, ground, walk_left, walk_right, aaah);
  input clk;
  input areset;
  input bump_left;
  input bump_right;
  input ground;
  output walk_left;
  output walk_right;
  output aaah;
  reg [1:0] state;
  always @(posedge clk) begin
    if (areset) state <= 2'd0;
    else case (state)
      2'd0: begin
        if (bump_left | bump_right | ground) state <= 2'd0;
        else state <= 2'd1;
      end
      2'd1: begin
        if (bump_left & ~bump_right & ground) state <= 2'd2;
        else if (bump_right & ~bump_left & ground) state <= 2'd3;
        else if (~(bump_left | bump_right) & ground) state <= 2'd1;
        else state <= 2'd0;
      end
      2'd2: begin
        if (~bump_left | bump_right | ground) state <= 2'd2;
        else state <= 2'd1;
      end
      2'd3: begin
        if (bump_left & ~bump_right & ground) state <= 2'd3;
        else if (~bump_right | bump_left & ground) state <= 2'd0;
        else state <= 2'd1;
      end
    endcase
  end
  assign walk_left = (state == 2'd1) | (state == 2'd2);
  assign walk_right = (state == 2'd1) | (state == 2'd3);
  assign aaah = ~ground & (bump_left | bump_right);
endmodule

