module TopModule(
  input  in,
  input  [9:0] state,
  output [9:0] next_state,
  output out1,
  output out2
);
  // One-hot encoded state names, for readability:
  parameter S0 = 10'b0000000001;
  parameter S1 = 10'b0000000010;
  parameter S2 = 10'b0000000100;
  parameter S3 = 10'b0000001000;
  parameter S4 = 10'b0000010000;
  parameter S5 = 10'b0000100000;
  parameter S6 = 10'b0001000000;
  parameter S7 = 10'b0010000000;
  parameter S8 = 10'b0100000000;
  parameter S9 = 10'b1000000000;

  // State transition function: combinational multiplexer that goes from
  // one-hot encoded state names to the next one-hot encoded state name.
  // This is the same as the state transition function in the previous
  // model, but now it's one-hot encoded and combined with a combinational
  // multiplexer.
  wire [9:0] next_state_comb = ~state |
    (S0 & (1'b0 ? S0 : S0)) |
    (S1 & (in ? S1 : S2)) |
    (S2 & (1'b0 ? S0 : S3)) |
    (S3 & (1'b0 ? S0 : S4)) |
    (S4 & (1'b0 ? S0 : S5)) |
    (S5 & (1'b0 ? S8 : S6)) |
    (S6 & (1'b0 ? S9 : S7)) |
    (S7 & (1'b0 ? S0 : (1'b0 ? S7 : S7))) |
    (S8 & (1'b0 ? S0 : S1)) |
    (S9 & (1'b0 ? S0 : S1));

  // Output function: combinational multiplexer that goes from one-hot
  // encoded state names to the corresponding outputs out1 and out2.
  // This is the same as the output function in the previous model.
  assign {out1, out2} = (1'b1 ? 2'b00 :
    (S0 & 2'b00) |
    (S1 & 2'b00) |
    (S2 & 2'b00) |
    (S3 & 2'b00) |
    (S4 & 2'b00) |
    (S5 & 2'b01) |
    (S6 & 2'b10) |
    (S7 & 2'b00) |
    (S8 & 2'b00) |
    (S9 & 2'b11));

  // The next_state port is just the one-hot encoded transition function.
  assign next_state = next_state_comb;
endmodule

