module TopModule (
    input  in,
    input  [9:0] state,
    output [9:0] next_state,
    output out1,
    output out2);

    // 10-bit one-hot state encoding: S0 is state[0], S1 is state[1], etc.
    // Transition to the next state on the next cycle given the current state
    // and the current inputs.
    // The outputs are zero in every state except the one specified (out1=1 and
    // out2=0 for the S3 state, for example).
    // The "id" function is used to force a constant combinational value to the
    // output, so that the model can be simulated using a simple always block
    // (no FSM template).
    function [9:0] id (input [9:0] x); begin id = x; end endfunction
    function [9:0] next (input [9:0] s, input in); begin
        case (s)
            10'b0000000001: next = id(10'b0000000010);
            10'b0000000010: next = (in ? id(10'b0000000100) : id(10'b0000000001));
            10'b0000000100: next = (in ? id(10'b0000001000) : id(10'b0000000010));
            10'b0000001000: next = (in ? id(10'b0000010000) : id(10'b0000000100));
            10'b0000010000: next = (in ? id(10'b0000100000) : id(10'b0000001000));
            10'b0000100000: next = (in ? id(10'b0001000000) : id(10'b0000010000));
            10'b0001000000: next = (in ? id(10'b0010000000) : id(10'b0000100000));
            10'b0010000000: next = (in ? id(10'b0100000000) : id(10'b0001000000));
            10'b0100000000: next = (in ? id(10'b1000000000) : id(10'b0010000000));
            10'b1000000000: next = (in ? id(10'b0000000001) : id(10'b0100000000));
            default:        $display("Bad state: %b", s);
        endcase
    endfunction
    assign next_state = next(state, in);
    assign out1 = (state == 10'b0000001100);
    assign out2 = (state == 10'b0000001010);
endmodule

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output [255:0] q
);
    reg [255:0] q_reg;
    reg [255:0] q_next;

    integer i, j;
    reg [3:0] neighbours;
    reg [255:0] rows [0:15];

    always @(*) begin
        for (i = 0; i < 16; i = i + 1) begin
            rows[i] = q_reg[(i+1)*16-1:i*16];
        end
    end

    always @(*) begin
        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                neighbours = 0;
                neighbours = neighbours + rows[(i-1+16)%16][(j-1+16)%16];
                neighbours = neighbours + rows[(i-1+16)%16][j];
                neighbours = neighbours + rows[(i-1+16)%16][(j+1)%16];
                neighbours = neighbours + rows[i][(j-1+16)%16];
                neighbours = neighbours + rows[i][(j+1)%16];
                neighbours = neighbours + rows[(i+1)%16][(j-1+16)%16];
                neighbours = neighbours + rows[(i+1)%16][j];
                neighbours = neighbours + rows[(i+1)%16][(j+1)%16];
                if (neighbours == 3) q_next[i*16+j] = 1;
                else if (neighbours == 2) q_next[i*16+j] = q_reg[i*16+j];
                else q_next[i*16+j] = 0;
            end
        end
    end

    always @(posedge clk) begin
        if (load) q_reg <= data;
        else q_reg <= q_next;
    end

    assign q = q_reg;
endmodule

module GameOfLife16x16(input clk, input load, input [255:0] data, output [255:0] q);
    reg [255:0] next_state;
    integer i;
    always @(*) begin
        for (i = 0; i < 256; i = i + 1) begin
            // Calculate the toroidal neighbour count (the neighbour count
            // modulo 16 is calculated for each neighbour, and the sum is
            // taken modulo 2 to determine whether the cell should live or
            // die).
            integer n = (data[(i + 15) % 256] + data[(i + 1) % 256] +
                         data[(i + 16) % 256] + data[(i + 14) % 256] +
                         data[(i + 256 + 15) % 256] + data[(i + 256 + 1) % 256] +
                         data[(i + 256 + 16) % 256] + data[(i + 256 + 14) % 256] +
                         data[(i + 256 * 15) % 256] + data[(i + 256 * 1) % 256] +
                         data[(i + 256 * 16) % 256] + data[(i + 256 * 14) % 256] +
                         data[(i + 256 * 256 + 15) % 256] + data[(i + 256 * 256 + 1) % 256] +
                         data[(i + 256 * 256 + 16) % 256] + data[(i + 256 * 256 + 14) % 256] +
                         data[(i + 256 * 256 * 15) % 256] + data[(i + 256 * 256 * 1) % 256] +
                         data[(i + 256 * 256 * 16) % 256] + data[(i + 256 * 256 * 14) % 256]) % 2;
            next_state[i] = (n == 3 || (n == 2 && data[i] == 1)) ? 1 : 0;
        end
    end
    always @(posedge clk) begin
        if (load) q <= 256'd0;
        else q <= next_state;
    end
endmodule

module ToroidGameOfLife_16x16 (
    input  wire        clk,
    input  wire        load,
    input  wire [255:0] data,
    output reg  [255:0] q
);
    reg [255:0] next_q;
    integer i, j, k;
    begin
        // Register to hold the intermediate state
        always @(posedge clk) begin
            if (load) next_q <= data;
            else next_q <= q;
        end

        // Compute the next state
        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                integer neighbours = 0;
                for (k = 0; k < 8; k = k + 1) begin
                    integer x = (i + k + 16) % 16;
                    integer y = (j + k + 16) % 16;
                    neighbours += q[16*y + x];
                end
                neighbours -= q[16*j + i];
                if (neighbours < 2) next_q[16*j + i] <= 0;
                else if (neighbours == 2) next_q[16*j + i] <= q[16*j + i];
                else if (neighbours == 3) next_q[16*j + i] <= 1;
                else next_q[16*j + i] <= 0;
            end
        end

        // Update the output
        always @(posedge clk) begin
            q <= next_q;
        end
    end
endmodule

module ToroidGame(input clk, input load, input [255:0] data, output [255:0] q);
  reg [255:0] next_state;
  reg [255:0] curr_state;
  integer i;
  integer j;
  integer neighbours;

  // Compute the next state of the game, independent of the clock.
  always @(*) begin
    for (i = 0; i < 16; i = i + 1) begin
      for (j = 0; j < 16; j = j + 1) begin
        neighbours = curr_state[16*(i-1+16)+j]
                    + curr_state[16*(i-1+16)+(j-1+16)]
                    + curr_state[16*(i-1+16)+(j+1)%16]
                    + curr_state[16*(i+1)%16+(j-1+16)]
                    + curr_state[16*(i+1)%16+j]
                    + curr_state[16*(i+1)%16+(j+1)%16]
                    + curr_state[16*(i+1+16)%256+(j-1+16)]
                    + curr_state[16*(i+1+16)%256+j]
                    + curr_state[16*(i+1+16)%256+(j+1)%16];
        if (neighbours == 3) begin
          next_state[16*i+j] = 1;
        end else if (neighbours == 2 && curr_state[16*i+j] == 1) begin
          next_state[16*i+j] = 1;
        end else begin
          next_state[16*i+j] = 0;
        end
      end
    end
  end

  // Update the current state on the positive edge of the clock.
  always @(posedge clk) begin
    if (load) begin
      curr_state <= data;
    end else begin
      curr_state <= next_state;
    end
  end

  // Make the current state output immediately.
  assign q = curr_state;
endmodule

module TopModule(input clk, input load, input [255:0] data, output [255:0] q);
  reg [255:0] next_q, cur_q;
  integer i, j;
  always @(*) begin
    for (i = 0; i < 16; i = i + 1) begin
      for (j = 0; j < 16; j = j + 1) begin
        // Toroid wraparound: q[(i-1)%16][j] is the same as q[15][j] (the
        // top row), and q[i][(j-1)%16] is the same as q[i][15] (the right
        // column).
        integer neighbours = cur_q[(i-1)%16*16+(j-1)%16]
                          + cur_q[(i-1)%16*16+j]
                          + cur_q[(i-1)%16*16+(j+1)%16]
                          + cur_q[(i+1)%16*16+(j-1)%16]
                          + cur_q[(i+1)%16*16+j]
                          + cur_q[(i+1)%16*16+(j+1)%16]
                          + cur_q[i*16+(j-1)%16]
                          + cur_q[i*16+(j+1)%16];
        if (neighbours == 3) next_q[i*16+j] = 1;
        else if (neighbours == 2) next_q[i*16+j] = cur_q[i*16+j];
        else next_q[i*16+j] = 0;
      end
    end
  end
  always @(posedge clk) begin
    if (load) cur_q <= data;
    else cur_q <= next_q;
  end
  assign q = cur_q;
endmodule

module TopModule(
  input clk,
  input load,
  input [255:0] data,
  output [255:0] q
);
  reg [255:0] cells;
  genvar i, j;
  generate
    for (i = 0; i < 16; i = i + 1) begin
      for (j = 0; j < 16; j = j + 1) begin
        always @(posedge clk) begin
          if (load) begin
            cells[16*i+j] <= data[16*i+j];
          end else begin
            reg [3:0] neighbours = 0;
            neighbours += cells[16*(i-1+16)%16+(j-1+16)%16];
            neighbours += cells[16*(i-1+16)%16+(j+1)%16];
            neighbours += cells[16*(i+1)%16+(j-1+16)%16];
            neighbours += cells[16*(i+1)%16+(j+1)%16];
            neighbours += cells[16*(i-1+16)%16+j];
            neighbours += cells[16*(i+1)%16+j];
            neighbours += cells[16*i+(j-1+16)%16];
            neighbours += cells[16*i+(j+1)%16];
            if (neighbours == 3) begin
              cells[16*i+j] <= 1;
            end else if (neighbours == 2) begin
              cells[16*i+j] <= cells[16*i+j];
            end else if (neighbours == 1) begin
              cells[16*i+j] <= 0;
            end else begin
              cells[16*i+j] <= 0;
            end
          end
        end
      end
    end
  endgenerate
  assign q = cells;
endmodule

module TopModule(input clk, input load, input [255:0] data, output [255:0] q);
  reg [255:0] r;
  integer i;
  wire [255:0] n;
  for (i = 0; i < 256; i = i + 1) begin : rows
    // Transform the 16-bit row index to a 6-bit row index, so we can look up
    // the neighbours in one cycle (the SUBINSTANTIATED primitives do the
    // lookup in one cycle).
    wire [5:0] r = i[7:2];
    // The TRANSPOSE primitive transforms the columns into rows, so we get a
    // 16x16 grid of neighbours in one cycle (the SUBINSTANTIATED primitives
    // do the lookup in one cycle).
    TLATNTSCU6D16FFC140C t0 (.X(n[i]), .Z(r[i]));
    TLATNTSCU6D16FFC140C t1 (.X(n[i]), .Z(r[i+16]));
    TLATNTSCU6D16FFC140C t2 (.X(n[i]), .Z(r[i+32]));
    TLATNTSCU6D16FFC140C t3 (.X(n[i]), .Z(r[i+48]));
    TLATNTSCU6D16FFC140C t4 (.X(n[i]), .Z(r[i+64]));
    TLATNTSCU6D16FFC140C t5 (.X(n[i]), .Z(r[i+80]));
    TLATNTSCU6D16FFC140C t6 (.X(n[i]), .Z(r[i+96]));
    TLATNTSCU6D16FFC140C t7 (.X(n[i]), .Z(r[i+112]));
    TLATNTSCU6D16FFC140C t8 (.X(n[i]), .Z(r[i+128]));
    TLATNTSCU6D16FFC140C t9 (.X(n[i]), .Z(r[i+144]));
    TLATNTSCU6D16FFC140C t10 (.X(n[i]), .Z(r[i+160]));
    TLATNTSCU6D16FFC140C t11 (.X(n[i]), .Z(r[i+176]));
    TLATNTSCU6D16FFC140C t12 (.X(n[i]), .Z(r[i+192]));
    TLATNTSCU6D16FFC140C t13 (.X(n[i]), .Z(r[i+208]));
    TLATNTSCU6D16FFC140C t14 (.X(n[i]), .Z(r[i+224]));
    TLATNTSCU6D16FFC140C t15 (.X(n[i]), .Z(r[i+240]));
    TLATNTSCU6D16FFC140C t16 (.X(n[i]), .Z(r[i+256]));
    TLATNTSCU6D16FFC140C t17 (.X(n[i]), .Z(r[i+1]));
    TLATNTSCU6D16FFC140C t18 (.X(n[i]), .Z(r[i+17]));

module TopModule(input clk, input load, input [255:0] data, output [255:0] q);
    reg [255:0] cells;
    genvar i, j;
    integer neighbours;
    // Compute the neighbour count for (x, y), modulo toroid wraparound.
    function integer neigh(integer x, integer y);
        integer xp = (x == 15) ? 0 : (x == -1) ? 15 : x + 1;
        integer xm = (x == 0) ? 15 : (x == 16) ? 1 : x - 1;
        integer yp = (y == 15) ? 0 : (y == -1) ? 15 : y + 1;
        integer ym = (y == 0) ? 15 : (y == 16) ? 1 : y - 1;
        return cells[16*yp + xp] + cells[16*yp + xm] + cells[16*ym + xp] + cells[16*ym + xm] + cells[16*y + xp] + cells[16*y + xm] + cells[16*yp + x] + cells[16*ym + x];
    endfunction
    always @(posedge clk) begin
        if (load) cells <= data;
        else begin
            for (i = 0; i < 16; i = i + 1) begin
                for (j = 0; j < 16; j = j + 1) begin
                    neighbours = neigh(i, j);
                    if (cells[16*i + j] && (neighbours < 2 || 4 <= neighbours)) cells[16*i + j] <= 1'b0;
                    else if (!cells[16*i + j] && (neighbours == 3)) cells[16*i + j] <= 1'b1;
                end
            end
        end
    end
    assign q = cells;
endmodule

