module TopModule(input clk, input in, input reset, output reg [7:0] out_byte, output reg done);
  // The FSM has 4 states: IDLE, START, DATA, STOP.
  reg [1:0] state;
  // The bit counter counts the number of data bits we've received.
  reg [2:0] bit_counter;
  // The register holds the current byte we're receiving.
  reg [7:0] byte_register;
  // The register holds the previous value of the input, so we can detect
  // transitions from 1 to 0 (the start of a start bit, or the end of a
  // stop bit).
  reg prev_in;
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      bit_counter <= 3'b000;
      byte_register <= 8'b0;
      prev_in <= 1'b1;
      out_byte <= 8'b0;
      done <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // IDLE
          if (!in && prev_in) begin
            state <= 2'b01; // go to START
            bit_counter <= 3'b000;
          end
        end
        2'b01: begin // START
          if (bit_counter == 3'b000) begin
            byte_register <= 8'b0;
          end
          byte_register <= {in, byte_register[7:1]};
          bit_counter <= bit_counter + 1;
          if (bit_counter == 3'b100) begin
            state <= 2'b10; // go to DATA
          end
        end
        2'b10: begin // DATA
          if (bit_counter == 3'b100) begin
            byte_register <= {in, byte_register[7:1]};
            bit_counter <= bit_counter + 1;
          end
          if (bit_counter == 3'b101) begin
            state <= 2'b11; // go to STOP
            bit_counter <= 3'b000;
          end
        end
        2'b11: begin // STOP
          if (in) begin
            state <= 2'b00; // go to IDLE
            out_byte <= byte_register;
            done <= 1'b1;
          end
        end
      endcase
      prev_in <= in;
    end
  end
endmodule

module TopModule (
    input  clk,
    input  in,
    input  reset,
    output [7:0] out_byte,
    output done
);
    reg [2:0] state;
    reg [7:0] byte;
    reg [2:0] bitcount;
    reg done_reg;
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            byte <= 8'b0;
            bitcount <= 3'b000;
            done_reg <= 1'b0;
        end else begin
            case (state)
                3'b000: begin // Wait for start bit
                    if (in == 1'b0) begin
                        state <= 3'b001;
                        bitcount <= 3'b000;
                    end
                end
                3'b001: begin // Read data bits
                    byte <= {in, byte[7:1]};
                    bitcount <= bitcount + 1;
                    if (bitcount == 3'b111) begin
                        state <= 3'b010;
                    end else begin
                        state <= 3'b001;
                    end
                end
                3'b010: begin // Wait for stop bit
                    if (in == 1'b1) begin
                        state <= 3'b000;
                        done_reg <= 1'b1;
                    end else begin
                        state <= 3'b010;
                    end
                end
            endcase
        end
    end
    assign out_byte = byte;
    assign done = done_reg;
endmodule

