            case (state)
                3'b000: begin // Idle state. Wait for start bit.
                    if (in == 1'b0) begin
                        state <= 3'b001;
                        shift_reg <= 8'b00000000;
                    end
                end
                3'b001: begin // Shift in the first data bit.
                    shift_reg <= {in, shift_reg[7:1]};
