module TopModule(
    input  clk,
    input  a,
    input  b,
    output reg q,
    output reg state
);
    always @(posedge clk) begin
        q <= a & ~b | ~a & q;
        state <= q;
    end
endmodule

module TopModule(input clk, input a, input b, output reg q, output reg state);
  reg [1:0] comb;
  always @(*) begin
    case ({a, b})
      2'b00: comb = 2'b00;
      2'b01: comb = 2'b01;
      2'b10: comb = 2'b10;
      2'b11: comb = 2'b11;
    endcase
  end
  always @(posedge clk) begin
    state <= comb[1];
    q <= comb[0];
  end
endmodule

module TopModule (
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [1:0] state, nextstate;
    always @(posedge clk) begin
        if (!resetn) state <= `A;
        else state <= nextstate;
    end
    always @(*) begin
        case (state)
            `A: begin
                g = 3'b000;
                if (r == 3'b100) nextstate = `B;
                else if (r == 3'b010) nextstate = `C;
                else if (r == 3'b001) nextstate = `D;
                else nextstate = `A;
            end
            `B: begin
                g = 3'b001;
                if (r == 3'b100) nextstate = `B;
                else if (r == 3'b000) nextstate = `A;
                else nextstate = `C;
            end
            `C: begin
                g = 3'b010;
                if (r == 3'b010) nextstate = `C;
                else if (r == 3'b000) nextstate = `A;
                else nextstate = `B;
            end
            `D: begin
                g = 3'b000;
                if (r == 3'b000) nextstate = `A;
                else nextstate = `D;
            end
        endcase
    end
endmodule

module TopModule(input  wire        clk,
                 input  wire        resetn,
                 input  wire [2:0]  r,
                 output wire [2:0]  g);

  // State encoding: A=0, B=1, C=2, D=3.
  reg [1:0] state, nextstate;
  always @(*) begin
    case (state)
      2'b00: nextstate = (r == 3'b000) ? 2'b00 :
                         (r == 3'b001) ? 2'b01 :
                         (r == 3'b010) ? 2'b10 : 2'b11;
      2'b01: nextstate = (r == 3'b000) ? 2'b00 :
                         (r == 3'b001) ? 2'b01 :
                         (r == 3'b010) ? 2'b10 : 2'b01;
      2'b10: nextstate = (r == 3'b000) ? 2'b00 :
                         (r == 3'b001) ? 2'b10 :
                         (r == 3'b010) ? 2'b10 : 2'b01;
      2'b11: nextstate = (r == 3'b000) ? 2'b00 :
                         (r == 3'b001) ? 2'b01 :
                         (r == 3'b010) ? 2'b10 : 2'b10;
    endcase
  end
  always @(posedge clk) begin
    if (!resetn) state <= 2'b00;
    else         state <= nextstate;
  end

  // Continuous assignments (no flops) to compute the outputs g[i], which go
  // high for one cycle per stage of the FSM, i.e., the stage number.
  assign g = (state == 2'b00) ? 3'b000 :
             (state == 2'b01) ? 3'b001 :
             (state == 2'b10) ? 3'b011 : 3'b101;

endmodule

module TopModule(clk, resetn, r, g);
  input  clk;
  input  resetn;
  input  [2:0] r;
  output [2:0] g;
  reg [1:0] state, next_state;
  reg [2:0] r0, r1, r2;
  always @(*) begin
    case (state)
      A: if (r == 3'b000) next_state = A; else next_state = B;
      B: if (r == 3'b001) next_state = B; else next_state = A;
      C: if (r == 3'b010) next_state = C; else next_state = A;
      D: if (r == 3'b000) next_state = D; else next_state = A;
      default: next_state = A;
    endcase
  end
  always @(posedge clk) begin
    if (!resetn) state <= A;
    else state <= next_state;
    r0 <= (state == A && r == 3'b000) || (state == B && r == 3'b001) || (state == C && r == 3'b100) || (state == D && r == 3'b000);
    r1 <= (state == A && r == 3'b000) || (state == B && r == 3'b010) || (state == C && r == 3'b100) || (state == D && r == 3'b000);
    r2 <= (state == A && r == 3'b000) || (state == B && r == 3'b100) || (state == C && r == 3'b100) || (state == D && r == 3'b000);
  end
  assign g = {r0, r1, r2};
endmodule

module TopModule(input clk, input resetn, input [2:0] r, output [2:0] g);
  reg [2:0] s, next_s;
  always @(*) begin
    case (s)
      3'b001: next_s = r[0] ? 3'b100 : (r[1] ? 3'b010 : (r[2] ? 3'b101 : 3'b001));
      3'b010: next_s = r[0] ? 3'b010 : (r[1] ? 3'b001 : (r[2] ? 3'b101 : 3'b010));
      3'b100: next_s = r[0] ? 3'b001 : (r[1] ? 3'b100 : (r[2] ? 3'b101 : 3'b100));
      3'b101: next_s = r[0] ? 3'b001 : (r[1] ? 3'b001 : (r[2] ? 3'b010 : 3'b101));
      default: next_s = 3'b001;
    endcase
  end
  always @(posedge clk) begin
    if (!resetn) s <= 3'b001;
    else s <= next_s;
  end
  always @(*) begin
    case (s)
      3'b001: g = 3'b001;
      3'b010: g = 3'b010;
      3'b100: g = 3'b100;
      3'b101: g = 3'b101;
      default: g = 3'b000;
    endcase
  end
endmodule

module TopModule(clk, resetn, r, g);
  input         clk;
  input         resetn;
  input  [2:0]  r;
  output [2:0]  g;
  reg   [1:0]   state_table;
  reg   [2:0]   reg0;
  reg   [2:0]   reg1;
  reg   [2:0]   reg2;
  always @(*) begin
    case ({reg0, reg1, reg2, r})
      4'b0000: state_table = 2'd0;
      4'b1000: state_table = 2'd0;
      4'b0100: state_table = 2'd1;
      4'b1100: state_table = 2'd1;
      4'b0010: state_table = 2'd2;
      4'b1010: state_table = 2'd2;
      4'b0110: state_table = 2'd0;
      4'b1110: state_table = 2'd0;
      4'b0001: state_table = 2'd1;
      4'b1001: state_table = 2'd1;
      4'b0101: state_table = 2'd2;
      4'b1101: state_table = 2'd2;
      4'b0011: state_table = 2'd0;
      4'b1011: state_table = 2'd0;
      4'b0111: state_table = 2'd1;
      4'b1111: state_table = 2'd1;
    endcase
  end
  always @(posedge clk) begin
    if (!resetn) begin
      reg0 <= 3'd0;
      reg1 <= 3'd0;
      reg2 <= 3'd0;
    end else begin
      case (state_table)
        2'd0: begin
          reg0 <= 3'd1;
          reg1 <= 3'd0;
          reg2 <= 3'd0;
        end
        2'd1: begin
          reg0 <= 3'd0;
          reg1 <= 3'd1;
          reg2 <= 3'd0;
        end
        2'd2: begin
          reg0 <= 3'd0;
          reg1 <= 3'd0;
          reg2 <= 3'd1;
        end
      endcase
    end
  end
  assign g = {reg0, reg1, reg2};
endmodule

module TopModule (
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    state_t state, next_state;
    always @(posedge clk) begin
        if (!resetn) state <= A;
        else         state <= next_state;
    end
    always @(*) begin
        case (state)
            A: if (r == 3'b000) next_state = A;
               else if (r == 3'b001) next_state = B;
               else if (r == 3'b010) next_state = C;
               else next_state = D;
            B: if (r == 3'b000) next_state = A;
               else if (r == 3'b001) next_state = B;
               else next_state = A;
            C: if (r == 3'b000) next_state = A;
               else if (r == 3'b010) next_state = C;
               else next_state = A;
            D: if (r == 3'b000) next_state = A;
               else next_state = D;
        endcase
    end
    assign g = (state == A) ? 3'b000 :
               (state == B) ? 3'b001 :
               (state == C) ? 3'b010 : 3'b011;
endmodule

module TopModule(
    input  clk,
    input  resetn,
    input  [2:0] r,
    output [2:0] g
);
    reg [2:0] state, next_state;
    always @(*) begin
        case (state)
            3'b000: if (r == 3'b001) next_state = 3'b001; else if (r == 3'b010) next_state = 3'b010; else if (r == 3'b100) next_state = 3'b011; else next_state = 3'b000;
            3'b001: if (r == 3'b000) next_state = 3'b000; else next_state = 3'b001;
            3'b010: if (r == 3'b000) next_state = 3'b000; else next_state = 3'b010;
            3'b011: if (r == 3'b000) next_state = 3'b000; else next_state = 3'b011;
            default: next_state = 3'b000;
        endcase
    end
    always @(posedge clk) begin
        if (!resetn) state <= 3'b000;
        else state <= next_state;
    end
    assign g = (state == 3'b000) ? 3'b001 :
               (state == 3'b001) ? 3'b000 :
               (state == 3'b010) ? 3'b000 :
               (state == 3'b011) ? 3'b000 : 3'b000;
endmodule

module TopModule(input  clk, input  resetn, input [2:0] r, output [2:0] g);
    reg [2:0] state, next_state;
    always @(*) begin
        case (state)
            3'b001: next_state = (r == 3'b001) ? 3'b010 :
                                  (r == 3'b010) ? 3'b011 :
                                  (r == 3'b100) ? 3'b100 : 3'b001;
            3'b010: next_state = (r == 3'b001) ? 3'b001 : 3'b010;
            3'b011: next_state = (r == 3'b010) ? 3'b010 : 3'b001;
            3'b100: next_state = (r == 3'b100) ? 3'b100 : 3'b001;
        endcase
    end
    always @(posedge clk) begin
        if (~resetn) state <= 3'b001;
        else         state <= next_state;
    end
    assign g = (state == 3'b001) ? 3'b001 :
               (state == 3'b010) ? 3'b010 :
               (state == 3'b011) ? 3'b010 : 3'b100;
endmodule

module TopModule (
  input  clk,
  input  resetn,
  input  [2:0] r,
  output [2:0] g
);
  // State codes
  localparam A = 3'd0, B = 3'd1, C = 3'd2, D = 3'd3;
  reg [2:0] state, next_state;
  always @(posedge clk) state <= resetn ? next_state : A;
  // State table
  always @(*) begin
    case (state)
      A: next_state = r == 3'b000 ? A : r[0] ? B : C;
      B: next_state = r[0] ? B : A;
      C: next_state = r[1] ? C : A;
      D: next_state = r == 3'b000 ? D : A;
    endcase
  end
  // g outputs (continuous assignments inline, or an always block would be OK)
  assign g[0] = state == B;
  assign g[1] = state == C;
  assign g[2] = 1'b0; // g[2] is always 0, so it doesn't need to be in the FSM
endmodule

module TopModule(
  input  clk,
  input  resetn,
  input  [2:0] r,
  output [2:0] g
);
  reg [2:0] state;
  reg [2:0] next_state;
  reg [2:0] grant;

  always @(*) begin
    case (state)
      A: next_state = (r == 3'b000) ? A : (r == 3'b001) ? B : (r == 3'b010) ? C : D;
      B: next_state = (r == 3'b001) ? B : A;
      C: next_state = (r == 3'b010) ? C : A;
      D: next_state = (r == 3'b000) ? D : ((r == 3'b001) ? B : (r == 3'b010) ? C : A);
      default: next_state = 3'bxxx;
    endcase
  end

  always @(*) begin
    case (state)
      A: grant = (r == 3'b000) ? 3'b000 : (r == 3'b001) ? 3'b001 : (r == 3'b010) ? 3'b010 : 3'b111;
      B: grant = r == 3'b001 ? 3'b001 : 3'b000;
      C: grant = r == 3'b010 ? 3'b010 : 3'b000;
      D: grant = r == 3'b000 ? 3'b111 : (r == 3'b001 ? 3'b001 : (r == 3'b010 ? 3'b010 : 3'b000));
      default: grant = 3'bxxx;
    endcase
  end

  always @(posedge clk) begin
    if (!resetn) state <= A;
    else state <= next_state;
  end

  assign g = grant;
endmodule

