module TopModule(clk, reset, s, fr2, fr1, fr0, dfr);
  input clk;
  input reset;
  input [2:0] s;
  output fr2;
  output fr1;
  output fr0;
  output dfr;
  reg [1:0] state;
  reg [2:0] level;
  reg [2:0] prev_level;
  wire level_changed = (level != prev_level);
  assign fr2 = (state == 2);
  assign fr1 = (state == 1) | (state == 2);
  assign fr0 = (state != 0);
  assign dfr = (state == 1) & level_changed;
  always @(posedge clk) begin
    if (reset) begin
      state <= 0;
      level <= 0;
      prev_level <= 0;
    end else begin
      case (state)
        0: if (!s[0] && !s[1] && !s[2]) begin
             state <= 0;
             level <= 0;
             prev_level <= 0;
           end else if (s[0] && !s[1] && !s[2]) begin
             state <= 1;
             level <= 1;
             prev_level <= 0;
           end else if (s[0] && s[1] && !s[2]) begin
             state <= 2;
             level <= 2;
             prev_level <= 1;
           end else begin
             state <= 3;
             level <= 3;
             prev_level <= 2;
           end
        1: if (!s[0] && !s[1] && !s[2]) begin
             state <= 0;
             level <= 0;
             prev_level <= 1;
           end else if (s[0] && !s[1] && !s[2]) begin
             state <= 1;
             level <= 1;
             prev_level <= 0;
           end else if (s[0] && s[1] && !s[2]) begin
             state <= 2;
             level <= 2;
             prev_level <= 1;
           end else begin
             state <= 3;
             level <= 3;
             prev_level <= 2;
           end
        2: if (!s[0] && !s[1] && !s[2]) begin
             state <= 0;
             level <= 0;
             prev_level <= 2;
           end else if (s[0] && !s[1] && !s[2]) begin
             state <= 1;
             level <= 1;
             prev_level <= 0;
           end else if (s[0] && s[1] && !s[2]) begin
             state <= 2;
             level <= 2;
             prev_level <= 1;
           end else begin
             state <= 3;
             level <= 3;
             prev_level <= 2;
           end
        3: if (!s[0] && !s[1] && !s[2]) begin
             state <= 0;
             level <= 0;
             prev_level <= 3;
           end else if (s[0] && !s[1] && !s[2]) begin
             state <= 1;
             level <= 1;
             prev_level <= 0;
           end else if (s[0] && s[1] && !s[2]) begin
             state <= 2;
             level <= 2;
             prev_level <= 1;
           end else begin
             state <= 3;
             level <= 3;
             prev_level <= 2;
           end
      endcase
    end
  end
endmodule

module TopModule(
    input clk,
    input reset,
    input [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);
    reg [1:0] water_level;
    always @(*) begin
        case (s)
            3'b000: water_level = 2'b00;
            3'b001: water_level = 2'b01;
            3'b010: water_level = 2'b01;
            3'b011: water_level = 2'b10;
            3'b100: water_level = 2'b10;
            3'b101: water_level = 2'b10;
            3'b110: water_level = 2'b11;
            3'b111: water_level = 2'b11;
        endcase
    end
    reg [1:0] state, next_state;
    always @(*) begin
        case (state)
            2'b00: next_state = (water_level == 2'b00) ? 2'b00 : 2'b01;
            2'b01: next_state = (water_level == 2'b01) ? 2'b01 : 2'b10;
            2'b10: next_state = (water_level == 2'b10) ? 2'b10 : 2'b11;
            2'b11: next_state = 2'b11;
        endcase
    end
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            fr0 <= 1'b1;
            fr1 <= 1'b1;
            fr2 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            state <= next_state;
            fr0 <= (state == 2'b00) ? 1'b0 : 1'b1;
            fr1 <= (state == 2'b01) ? 1'b0 : 1'b1;
            fr2 <= (state == 2'b10) ? 1'b0 : 1'b1;
            dfr <= (water_level > state) ? 1'b1 : 1'b0;
        end
    end
