            FALL: begin
                aaah = 1'b1;
                if (ground_reg) begin
                    if (bump_left_reg) begin
                        next_state = WALK_LEFT;
                    end else if (bump_right_reg) begin
                        next_state = WALK_RIGHT;
                    end else begin
                        next_state = WALK_LEFT;
                    end
                end else begin
                    next_state = FALL;
                end
            end
            DIG: begin
                digging = 1'b1;
                if (ground_reg) begin
                    next_state = WALK_LEFT;
                end else begin
                    next_state = DIG;
                end
