                history <= predict_taken ? pc_xor_history_next_inc : pc_xor_history_next_dec;
                pc_xor_history <= pc_xor_history_next;
            end
            if (train_valid) begin
                pht[pc_xor_history] <= train_mispredicted ? 2'b00 : (train_taken ? pht[pc_xor_history] + 1 : pht[pc_xor_history] - 1);
                history <= train_mispredicted ? train_history : history;
                pc_xor_history <= train_pc ^ history;
            end
        end
    end
endmodule

module TopModule (
    input  clk,
    input  areset,
    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
