    reg [6:0] global_history;
    reg [6:0] predict_index;
    reg [1:0] predict_counter;
    reg [6:0] train_index;
    always @(posedge clk) begin
        if (areset) begin
            for (int i = 0; i < 128; i = i + 1) begin
                pht[i] <= 2'b00;
            end
            global_history <= 7'b0;
        end else begin
            if (predict_valid) begin
                predict_index <= global_history ^ predict_pc;
                predict_counter <= pht[predict_index];
                predict_history <= global_history;
                predict_taken <= predict_counter[1];
                if (predict_valid && predict_taken) begin
                    global_history <= global_history << 1 | 1;
                end else begin
                    global_history <= global_history << 1;
                end
            end
            if (train_valid) begin
                train_index <= train_history ^ train_pc;
                if (train_mispredicted) begin
                    global_history <= train_history;
                end
                case ({train_taken, pht[train_index]})
                    2'b00: pht[train_index] <= 2'b01;
                    2'b01: pht[train_index] <= 2'b10;
                    2'b10: pht[train_index] <= 2'b11;
                    2'b11: pht[train_index] <= 2'b00;
                endcase
            end
        end
