  reg [6:0] history_reg;
  reg [6:0] index;
  reg [1:0] counter_out;
  wire predict_counter_out = counter_out[predict_taken];
  always @(*) index = predict_pc ^ history_reg;
  always @(posedge clk) begin
    if (areset) begin
      for (int i = 0; i < 128; i = i + 1) begin pht[i] <= 2'b00; end
      history_reg <= 7'd0;
    end else begin
      if (train_valid) begin
        if (train_mispredicted) history_reg <= train_history;
        pht[train_pc ^ history_reg] <= {pht[train_pc ^ history_reg][0] & ~train_taken | ~pht[train_pc ^ history_reg][0] & train_taken, pht[train_pc ^ history_reg][1] & ~train_taken | ~pht[train_pc ^ history_reg][1] & train_taken};
      end
      if (predict_valid) begin
        history_reg <= {history_reg[5:0], predict_counter_out};
      end
    end
  end
  assign counter_out = pht[index];
  assign predict_taken = predict_counter_out[1];
  assign predict_history = history_reg;
endmodule

module TopModule(input  clk, input  areset,
                 input  predict_valid,
                 input  [6:0] predict_pc,
