    reg [6:0] history;
    integer index;
    always @(*) index = predict_pc ^ history;
    always @(*) begin
        predict_taken = pht[index][1];
        predict_history = history;
    end
    always @(posedge clk) begin
        if (areset) begin
            for (integer i = 0; i < 128; i = i + 1) pht[i] <= 2'b01;
            history <= 7'd0;
        end else begin
            if (predict_valid) begin
                history <= {history[5:0], predict_taken};
            end
            if (train_valid) begin
                if (train_mispredicted) begin
                    history <= train_history;
                end
                pht[index] <= {pht[index][0], train_taken};
            end
        end
    end
endmodule

module TopModule(
  input  clk,
  input  areset, // async reset

  // Prediction interface: Fetch stage -> Execute stage pipeline registers
  input  predict_valid, // high if predict_pc is valid
  input  [6:0] predict_pc, // PC of instruction to predict branch for
  output reg predict_taken, // predicted branch direction
  output reg [6:0] predict_history, // the current global branch history

  // Training interface: Execute stage -> Fetch stage pipeline registers
  input  train_valid, // high if train_pc is valid
  input  train_taken, // actual branch outcome
  input  train_mispredicted, // pipeline flush requested
  input  [6:0] train_history, // the global branch history at the time of the
                                // branch (before any updates to the PHT)
  input  [6:0] train_pc // PC of instruction to train the branch predictor on
);

  // Gshare indexing function: Hash the PC and history to a 7-bit index.
  function [6:0] index(input [6:0] pc, input [6:0] history);
    index = pc ^ history;
  endfunction

  // 128-entry PHT: Saturating counter accesses (inc, dec, update).
  reg [1:0] pht [0:127];
  always @(posedge clk) begin
    if (areset) begin
      for (int i = 0; i < 128; i = i + 1) pht[i] <= 2'd1;
    end else begin
      if (train_valid) begin
        case (pht[index(train_pc, train_history)])
          2'd0: pht[index(train_pc, train_history)] <= train_taken ? 2'd1 : 2'd2;
          2'd1: pht[index(train_pc, train_history)] <= train_taken ? 2'd2 : 2'd0;
          2'd2: pht[index(train_pc, train_history)] <= train_taken ? 2'd3 : 2'd1;
          2'd3: pht[index(train_pc, train_history)] <= train_taken ? 2'd3 : 2'd2;
        endcase
      end
    end
  end

  // Prediction combinational logic: Look up the PHT and saturating counter to
  // produce the predicted branch direction and update the global branch history.
  always @* begin
    if (predict_valid) begin
      predict_taken = pht[index(predict_pc, predict_history)] > 1;
      predict_history = (predict_history << 1) | predict_taken;
    end
  end

  // Training combinational logic: Update the PHT and the global branch history
  // as requested on the training interface.
  always @* begin
    if (train_valid) begin
      case (pht[index(train_pc, train_history)])
        2'd0: pht[index(train_pc, train_history)] <= train_taken ? 2'd1 : 2'd2;
        2'd1: pht[index(train_pc, train_history)] <= train_taken ? 2'd2 : 2'd0;
        2'd2: pht[index(train_pc, train_history)] <= train_taken ? 2'd3 : 2'd1;
        2'd3: pht[index(train_pc, train_history)] <= train_taken ? 2'd3 : 2'd2;
      endcase
      if (train_mispredicted) begin
        predict_history <= (predict_history << 1) | train_taken;
      end
    end
  end

endmodule

module TopModule(
    input  clk,
    input  areset,
    input  predict_valid,
    input  [6:0] predict_pc,
    output reg predict_taken,
    output reg [6:0] predict_history,
    input  train_valid,
    input  train_taken,
    input  train_mispredicted,
    input  [6:0] train_history,
    input  [6:0] train_pc
);
    reg [1:0] counter [0:127];
    reg [6:0] history;
    always @(posedge clk) begin
        if (areset) begin
            counter <= '{128{2'b00}};
            history <= 7'b0;
            predict_taken <= 1'b0;
            predict_history <= 7'b0;
        end else begin
            if (predict_valid) begin
                predict_taken <= counter[{history, predict_pc}] >= 2;
                predict_history <= history;
            end
            if (train_valid) begin
                counter[{history, train_pc}] <= (train_taken && !train_mispredicted) ? counter[{history, train_pc}] + 2'b01 : (train_taken && train_mispredicted) ? counter[{history, train_pc}] - 2'b01 : counter[{history, train_pc}];
                history <= (train_mispredicted) ? train_history : history << 1 | train_taken;
            end
        end
    end
endmodule

module fsm(input clk, input reset, input [7:0] in, output reg done);
    reg [2:0] state;
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            done <= 1'b0;
        end else begin
            case (state)
                3'b000: if (in[3]) state <= 3'b001;
                3'b001: if (in[3]) state <= 3'b010;
                3'b010: if (in[3]) state <= 3'b011;
                3'b011: state <= 3'b100; done <= 1'b1;
                3'b100: state <= 3'b000;
            endcase
        end
    end
endmodule

module fsm(clk, reset, in, done, out);
  input clk, reset, in;
  output reg done = 0;
  output reg [1:0] state = 2'b00;
  output reg [2:0] count = 3'b000;
  always @(posedge clk) begin
    if (reset) begin
      done <= 0;
      state <= 2'b00;
      count <= 3'b000;
    end else begin
      case (state)
        2'b00: begin // Idle
          if (in == 1'b1) begin
            state <= 2'b01;
          end
        end
        2'b01: begin // Wait for byte 2
          count <= count + 1;
          if (count == 3'b011) begin
            state <= 2'b10;
          end
        end
        2'b10: begin // Wait for byte 3
          count <= count + 1;
          if (count == 3'b111) begin
            done <= 1;
            state <= 2'b00;
          end
        end
        default: begin
          state <= 2'b00;
        end
      endcase
    end
  end
  assign out = count == 3'b011;
endmodule

module FSM (
    input clk,
    input reset,
    input in,
    output reg start = 0,
    output reg done = 0
);
    reg [2:0] state = 3'b000;
    always @(posedge clk) begin
        if (reset) begin
            state <= 3'b000;
            start <= 0;
            done <= 0;
        end else begin
            case (state)
                3'b000: if (in) state <= 3'b001;
                3'b001: if (~in) state <= 3'b010;
                3'b010: if (in) state <= 3'b011;
                3'b011: if (~in) state <= 3'b100;
                3'b100: if (in) state <= 3'b101;
                3'b101: if (~in) state <= 3'b110;
                3'b110: if (in) state <= 3'b111;
                3'b111: begin
                    state <= 3'b000;
                    start <= 1;
                end
            endcase
            if (start) done <= 1;
            else done <= 0;
        end
    end
end

// Datapath to output the 24-bit (3 byte) message
module Datapath (
    input clk,
    input reset,
    input [7:0] in,
    input start,
    output reg [23:0] out_bytes = 24'b0,
    output reg done = 0
);
    reg [2:0] byte_index = 3'b000;
    always @(posedge clk) begin
        if (reset) begin
            byte_index <= 3'b000;
            out_bytes <= 24'b0;
            done <= 0;
        end else begin
            if (start) byte_index <= 3'b000;
            else if (byte_index < 3) byte_index <= byte_index + 1;
            if (start) out_bytes[byte_index*8+7:byte_index*8] <= in;
            if (byte_index == 2) done <= 1;
            else done <= 0;
        end
    end
end

