module FSM (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [1:0] state,
    output reg done
);
    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            done <= 1'b0;
        end else begin
            case (state)
                2'b00: begin
                    if (in[3] == 1'b1) state <= 2'b01;
                end
                2'b01: begin
                    if (in[3] == 1'b1) state <= 2'b10;
                    else state <= 2'b00;
                end
                2'b10: begin
                    if (in[3] == 1'b1) begin
                        state <= 2'b00;
                        done <= 1'b1;
                    end else state <= 2'b00;
                end
                default: state <= 2'b00;
            endcase
        end
    end
end

// Datapath that outputs the 24-bit (3-byte) message whenever a packet is
// received. The reset signal is active high, synchronous, and takes
// precedence over the FSM. out_bytes needs to be valid whenever the done
// signal is asserted.
module Datapath (
    input  clk,
    input  reset,
    input  [7:0] in,
    input  done,
    output reg [23:0] out_bytes
);
    reg [7:0] bytes [0:2];
    integer i;
    always @(posedge clk) begin
        if (reset) begin
            for (i = 0; i < 3; i = i + 1) bytes[i] <= 8'h00;
            out_bytes <= 24'h000000;
        end else begin
            if (done) out_bytes <= 24'h000000 | {bytes[0], bytes[1], bytes[2]};
            bytes[0] <= in;
            bytes[1] <= bytes[0];
            bytes[2] <= bytes[1];
        end
    end
end

// Top-level module that instantiates the FSM and datapath, and wires them
// together.
module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output [23:0] out_bytes,
    output done
);
    wire [1:0] state;
    wire done_int;
    FSM fsm (.clk(clk), .reset(reset), .in(in), .state(state), .done(done_int));
    Datapath datapath (.clk(clk), .reset(reset), .in(in), .done(done_int), .out_bytes(out_bytes));
    assign done = done_int;
endmodule

module FSM(clk, reset, in, done, shift_bytes);
  input clk, reset, in;
  output reg done;
  output reg [10:0] shift_bytes;
  reg [1:0] stage;
  always @(posedge clk) begin
    if (reset) begin
      done <= 1'b0;
      shift_bytes <= 11'd0;
      stage <= 2'd0;
    end else begin
      case (stage)
        2'd0: begin // Waiting for the first byte.
          if (in[3]) begin
            shift_bytes <= 11'b10000000001;
            stage <= 2'd1;
          end
        end
        2'd1: begin // Waiting for the second byte.
          shift_bytes <= {shift_bytes[10:0], in};
          if (&shift_bytes[10:8]) begin
            stage <= 2'd2;
          end
        end
        2'd2: begin // Waiting for the third byte.
          shift_bytes <= {shift_bytes[10:0], in};
          done <= 1'b1;
          stage <= 2'd0;
        end
      endcase
    end
  end
endmodule

module FSM (
    input clk,
    input reset,
    input [7:0] in,
    output reg done = 0
);
    reg [2:0] state = 0;
    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            done <= 0;
        end else begin
            case (state)
                0: if (in[3] == 1) state <= 1;
                1: state <= 2;
                2: if (in[3] == 0) state <= 0;
            endcase
            done <= (state == 2);
        end
    end
endmodule

// One-hot encoding of the 4 states of the FSM.
// State NUMBER_OF_ZEROS is the reset state.
parameter STATE_0 = 3'b000,
          STATE_1 = 3'b001,
          STATE_2 = 3'b010,
          STATE_3 = 3'b011,
          STATE_4 = 3'b100;

// The four stages of the FSM.
reg [2:0] state, next_state;
reg [23:0] bytes;
reg [31:0] counter;

// The register that determines the state transitions.
always @(posedge clk) begin
  if (reset) begin
    state <= STATE_0;
    bytes <= 24'h0;
    counter <= 32'h0;
  end else begin
    state <= next_state;
    if (state == STATE_4) begin
      counter <= 32'h0;
    end else begin
      counter <= counter + 32'h1;
    end
    if (state == STATE_3) begin
      bytes <= {in, bytes[23:8]};
    end
  end
end

// The register that determines the next state.
always @(*) begin
  case (state)
    STATE_0: next_state = in ? STATE_1 : STATE_0;
    STATE_1: next_state = (counter == 32'h1) ? STATE_2 : STATE_1;
    STATE_2: next_state = (counter == 32'h2) ? STATE_3 : STATE_2;
    STATE_3: next_state = (counter == 32'h3) ? STATE_4 : STATE_3;
    STATE_4: next_state = STATE_0;
  endcase
end

// The combinational logic that determines the outputs.
assign done = (state == STATE_4);
assign out_bytes = done ? bytes : 24'h0;
endmodule

module FSM(input clk, input reset, input [7:0] in, output reg done,
           output reg [23:0] out_bytes);
  reg [1:0] state;
  reg [23:0] shift_reg;
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      shift_reg <= 24'h0;
      done <= 1'b0;
    end else begin
      case (state)
        2'b00: begin // wait stage
          if (in[3] == 1'b1) state <= 2'b01;
        end
        2'b01: begin // byte1 stage
          shift_reg <= {in, shift_reg[23:8]};
          state <= 2'b10;
        end
        2'b10: begin // byte2 stage
          shift_reg <= {in, shift_reg[23:8]};
          state <= 2'b11;
        end
        2'b11: begin // byte3 stage
          shift_reg <= {in, shift_reg[23:8]};
          state <= 2'b00;
          done <= 1'b1;
        end
      endcase
    end
  end
  assign out_bytes = shift_reg;
endmodule

module datapath(input clk, input reset, input [7:0] in, output reg [23:0] out_bytes);
  reg [23:0] bytes = 24'h0;
  reg [1:0] byte_count = 2'b0;
  always @(posedge clk) begin
    if (reset) begin
      bytes <= 24'h0;
      byte_count <= 2'b0;
    end else begin
      if (byte_count == 2'b0) begin
        // Waiting for the first byte.
        if (in[3] == 1) begin
          bytes <= {8'h0, 8'h0, in};
          byte_count <= 2'b1;
        end
      end else if (byte_count == 2'b1) begin
        // Waiting for the second byte.
        bytes <= {bytes[15:0], in};
        byte_count <= 2'b2;
      end else begin
        // Waiting for the third byte; output the message.
        bytes <= {bytes[7:0], in};
        byte_count <= 2'b3;
      end
    end
  end
  always @(*) out_bytes = bytes;
endmodule

module fsm (
    input clk, reset,
    input [7:0] in,
    output reg done
