    always @(posedge clk) begin
        if (reset) begin
            state <= 4'd0;
            done <= 1'b0;
        end else begin
            case (state)
                4'd0: begin
                    if (in[3] == 1'b1) state <= 4'd1;
                end
                4'd1: begin
                    if (in[0] == 1'b1) state <= 4'd2;
                    else               state <= 4'd0;
                end
                4'd2: begin
                    if (in[0] == 1'b0) state <= 4'd0;
                    else               state <= 4'd3;
                end
                4'd3: done <= 1'b1; state <= 4'd0;
            endcase
        end
    end
endmodule

module TopModule(
  input  clk,
  input  areset,
  input  bump_left,
  input  bump_right,
  input  ground,
  input  dig,
  output walk_left,
  output walk_right,
  output aaah,
  output digging
);
  reg [2:0] state;
  reg [19:0] fall_counter;
  always @(posedge clk) begin
    if (areset) begin
      state <= 3'b001;
      fall_counter <= 20'd0;
    end else begin
      case (state)
        3'b001: if (bump_left) begin
                  state <= 3'b010;
                  fall_counter <= 20'd0;
                end else if (bump_right) begin
                  state <= 3'b001;
                  fall_counter <= 20'd0;
                end else if (ground) begin
                  state <= 3'b001;
                  fall_counter <= 20'd0;
                end else begin
                  state <= 3'b100;
                  fall_counter <= 20'd0;
                end
        3'b010: if (bump_left) begin
                  state <= 3'b010;
                  fall_counter <= 20'd0;
                end else if (bump_right) begin
                  state <= 3'b001;
                  fall_counter <= 20'd0;
                end else if (ground) begin
                  state <= 3'b010;
                  fall_counter <= 20'd0;
                end else begin
                  state <= 3'b100;
                  fall_counter <= 20'd0;
                end
        3'b100: if (fall_counter == 20'd19) begin
                  state <= 3'b100;
                  fall_counter <= 20'd20;
                end else if (ground) begin
                  if (dig) begin
                    state <= 3'b110;
                    fall_counter <= 20'd0;
                  end else begin
                    state <= 3'b001;
                    fall_counter <= 20'd0;
                  end
                end else begin
                  state <= 3'b100;
                  fall_counter <= fall_counter + 1'd1;
                end
        3'b110: if (ground) begin
                  state <= 3'b111;
                  fall_counter <= 20'd0;
                end else begin
                  state <= 3'b110;
                  fall_counter <= 20'd0;
                end
        3'b111: if (fall_counter == 20'd19) begin
                  state <= 3'b111;
                  fall_counter <= 20'd20;
                end else if (ground) begin
                  state <= 3'b001;
                  fall_counter <= 20'd0;
                end else begin
                  state <= 3'b111;
                  fall_counter <= fall_counter + 1'd1;
                end
      endcase
    end
  end
  assign walk_left = (state == 3'b001);
  assign walk_right = (state == 3'b010);
  assign aaah = (state == 3'b100);
  assign digging = (state == 3'b110);
endmodule

module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);
    reg [1:0] state;
    reg [5:0] falling_count;
    always @(posedge clk) begin
        if (areset) begin
            state <= 2'b00;
            falling_count <= 6'd0;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
        end else begin
            case (state)
                2'b00: begin // walking left
                    if (bump_left) begin
                        state <= 2'b01;
                        walk_left <= 1'b0;
                        walk_right <= 1'b1;
                        aaah <= 1'b0;
                        digging <= 1'b0;
                        falling_count <= 6'd0;
                    end else if (bump_right) begin
                        state <= 2'b01;
                        walk_left <= 1'b1;
                        walk_right <= 1'b0;
                        aaah <= 1'b0;
                        digging <= 1'b0;
                        falling_count <= 6'd0;
                    end else if (ground && !dig) begin
                        walk_left <= 1'b0;
                        walk_right <= 1'b0;
                        aaah <= 1'b1;
                        digging <= 1'b0;
                        falling_count <= falling_count + 6'd1;
                        if (falling_count == 6'd20) begin
                            walk_left <= 1'b0;
                            walk_right <= 1'b0;
                            aaah <= 1'b0;
                            digging <= 1'b0;
                        end
