    output reg walk_right,
    output reg aaah,
    output reg digging
);
    // Define the states of the finite state machine.
    localparam LEFT = 2'b00, RIGHT = 2'b01, FALLING = 2'b10, DIGGING = 2'b11;
    reg [1:0] state, next_state;

    // Registers for the falling counter.
    reg [5:0] falling_counter;
    reg falling_counter_en;

    // Combinational logic for the next state and outputs.
    always @* begin
        next_state = state;
        walk_left = 1'b0;
        walk_right = 1'b0;
        aaah = 1'b0;
        digging = 1'b0;
        falling_counter_en = 1'b0;
        case (state)
            LEFT: begin
                walk_left = 1'b1;
                if (bump_left) next_state = RIGHT;
                else if (ground) next_state = LEFT;
                else begin
                    next_state = FALLING;
                    falling_counter_en = 1'b1;
                end
            end
            RIGHT: begin
                walk_right = 1'b1;
                if (bump_right) next_state = LEFT;
                else if (ground) next_state = RIGHT;
                else begin
                    next_state = FALLING;
                    falling_counter_en = 1'b1;
                end
            end
            FALLING: begin
                aaah = 1'b1;
                falling_counter_en = 1'b1;
                if (ground) next_state = (dig ? DIGGING : state);
            end
            DIGGING: begin
                digging = 1'b1;
                if (ground) begin
                    next_state = (dig ? DIGGING : FALLING);
                    falling_counter_en = 1'b1;
                end
            end
        endcase
    end

    // Sequential logic for the current state and falling counter.
    always @(posedge clk) begin
        if (areset) state <= LEFT;
        else state <= next_state;
        if (falling_counter_en) falling_counter <= falling_counter + 1;
        else falling_counter <= 6'd0;
    end

    // Reset the machine if it falls for too long.
    always @(posedge clk) begin
        if (falling_counter == 6'd20) state <= LEFT;
    end
