  output reg pulse_out
);
  reg reg0;
  always @(posedge clk) begin
    reg0 <= pulse;
    pulse_out <= ~reg0 & reg;
  end
endmodule

module Timer (
    input clk,
    input reset,
    input enable,
    input [3:0] delay,
    output reg [3:0] count,
    output reg counting,
    output reg done
);
    reg [3:0] remaining;
    reg [15:0] counter;
    always @(posedge clk) begin
        if (reset) begin
            count <= 4'd0;
            remaining <= 4'd0;
            counter <= 16'd0;
            counting <= 1'b0;
            done <= 1'b0;
        end else if (enable) begin
            if (counter == 16'd999) begin
                counter <= 16'd0;
                remaining <= remaining - 4'd1;
                if (remaining == 4'd0) begin
                    counting <= 1'b0;
                    done <= 1'b1;
                end
            end else begin
                counter <= counter + 16'd1;
            end
            if (counting) begin
                count <= remaining;
            end
        end
    end
    always @(posedge clk) begin
        if (reset) begin
            counting <= 1'b0;
        end else if (!counting && enable) begin
            remaining <= delay;
            counter <= 16'd0;
            counting <= 1'b1;
            done <= 1'b0;
        end
    end
endmodule

module reg1 (input clk, input d, output reg q);
  always @(posedge clk) q <= d;
endmodule
